-- =====================================================================================================
-- T3 step 2 — centre Students and households (view + edit): five functions                 undo: migration_staff_students_down.sql
-- =====================================================================================================
-- Needs migration_org_foundation.sql (students.org_id / household_id, households, guardians, audit_row), migration_tutor_access.sql
-- (lessons.taught_by, trial) and migration_staff_home.sql only for the page. ADD-ONLY: five new functions, no table or column is touched.
--
-- WHAT IT IS: the centre's staff screen for students is just these functions. The page never writes a table; every rule is here, so it
-- holds for any caller (the page, a script, someone with their own copy of the app):
--   staff_students(org, q, filter, page, size)       the list: server-side search + paging (a centre can have 400+ students)
--   staff_student(org, student)                      one student's sheet: details, family + guardians (phone, email), subjects, next lessons
--   staff_save_student(org, student, name, level, notes, household, household_name, guardians)
--                                                    add (student = null, creates the household and its guardians in ONE step) or edit
--   staff_set_student_end(org, student, date)        "lessons run until" (same meaning as for solo tutors); date = null brings them back
--
-- WHO MAY CALL (decided for T3.1, 2026-11-25): an active OWNER or STAFF member of this CENTRE with the manage_students permission (owners
-- always). Nothing else:
--   not a member / a tutor / a parent / switched-off staff / a solo organisation / an unknown id  → NOT_FOUND (same words for all, so ids can't be probed)
--   staff of this centre WITHOUT manage_students (e.g. timetable-only)                           → NOT_ALLOWED
-- Centre tutors still have NO table access at all (CLAUDE.md): they never read students, households or guardians, and still see a parent's
-- contact only through tutor_my_lessons, and only when the centre switched on lessons.tutors_see_parent_contact (default off).
--
-- WHAT STAYS FIXED (integrity, not process): students belong to the CENTRE (org_id) and never to a solo organisation; a household, a guardian
-- or a student id from ANOTHER organisation is treated as "doesn't exist"; every write is validated here and leaves an audit_log row (the
-- generic row triggers on students / households / guardians record before + after, and each function adds one named summary entry).
-- NOTHING here needs a class, a room or a branch: a remote 1-to-1 centre adds a student with just a name and a parent's phone or email.
--
-- DATA-MODEL CHOICES (plain words):
--   * A HOUSEHOLD is the family (your "household id" sheet); GUARDIANS are the family's contacts (name, relation, phone, email). Siblings share one
--     household, so a phone number is edited once for all of them.
--   * students.tutor_id is NOT NULL and cascades on delete of that login. A centre's students must not disappear when a staff member's login is
--     removed, so a new student is filed under the centre OWNER's login (the organisation itself goes with the owner anyway).
--   * The MAIN contact of a family is its first guardian (the one added first; the list keeps the order they were typed in).
--   * students.contact and students.recipient_name are the older single-parent fields that tutor_my_lessons / messages / invoices read. They are
--     kept equal to the household's FIRST guardian, so those readers keep working (and a tutor sees the number only if the centre allows it).
--   * Discontinuing = students.end_date ("lessons run until", inclusive), exactly as for solo tutors: after it the student counts as
--     discontinued everywhere (staff_home, the list). Like the solo page it also switches the student's weekly slots off once the date has
--     passed, and back on when the student is brought back. Lessons already made are left alone.
--   * Trial is shown read-only here (a trial lesson in the last 30 days, in the centre's own timezone); flagging a trial is T3 step 5.
-- Run on the DEV project first. Safe to run twice.
-- =====================================================================================================

-- ---------------------------------------------------------------- the gate every function starts with (internal; not callable from the browser)
create or replace function public.staff_students_gate(p_org uuid) returns date
language plpgsql stable security definer set search_path = public as $$
declare tz text;
begin
  if auth.uid() is null then raise exception 'NOT_FOUND' using errcode = 'P0001'; end if;
  select o.timezone into tz from organisations o where o.id = p_org and o.kind = 'centre';
  if tz is null or not exists (select 1 from memberships m where m.org_id = p_org and m.user_id = auth.uid() and m.status = 'active'
                               and m.role in ('owner', 'staff')) then
    raise exception 'NOT_FOUND' using errcode = 'P0001';
  end if;
  if not org_can(p_org, 'manage_students') then
    raise exception 'NOT_ALLOWED: your account can''t manage students at this centre' using errcode = '42501';
  end if;
  return (now() at time zone tz)::date;                       -- the centre's own today
end $$;

-- ---------------------------------------------------------------- contacts: one place that validates and tidies a guardian
create or replace function public.staff_clean_guardian(g jsonb) returns jsonb
language plpgsql immutable set search_path = public as $$
declare nm text; rel text; ph text; em text; digits int;
begin
  if jsonb_typeof(g) is distinct from 'object' then raise exception 'BAD_GUARDIAN: a guardian must be an object' using errcode = 'P0001'; end if;
  nm  := nullif(trim(coalesce(g->>'name', '')), '');
  rel := nullif(trim(coalesce(g->>'relation', '')), '');
  ph  := nullif(trim(coalesce(g->>'phone', '')), '');
  em  := nullif(lower(trim(coalesce(g->>'email', ''))), '');
  if nm is null then raise exception 'BAD_GUARDIAN: give each parent or guardian a name' using errcode = 'P0001'; end if;
  if length(nm) > 120 then raise exception 'BAD_GUARDIAN: a guardian''s name is too long (120 characters at most)' using errcode = 'P0001'; end if;
  if rel is not null and length(rel) > 40 then raise exception 'BAD_GUARDIAN: the relation is too long (40 characters at most)' using errcode = 'P0001'; end if;
  if ph is null and em is null then
    raise exception 'BAD_GUARDIAN: give % a phone number or an email, so the centre can reach the family', nm using errcode = 'P0001'; end if;
  if ph is not null then
    digits := length(regexp_replace(ph, '\D', '', 'g'));
    if ph !~ '^[0-9+()\s-]{6,30}$' or digits < 6 or digits > 15 then
      raise exception 'BAD_GUARDIAN: that phone number doesn''t look right (%)', ph using errcode = 'P0001'; end if;
  end if;
  if em is not null and (length(em) > 254 or em !~ '^[^@\s]+@[^@\s]+\.[^@\s]+$') then
    raise exception 'BAD_GUARDIAN: that email address doesn''t look right (%)', em using errcode = 'P0001'; end if;
  return jsonb_build_object('id', nullif(g->>'id', ''), 'name', nm, 'relation', rel, 'phone', ph, 'email', em);
end $$;

-- ---------------------------------------------------------------- 1. the list
-- p_filter: 'active' (default) | 'ended' | 'trial' (a trial lesson in the last 30 days) | 'all'.  p_q searches the student's name and level, the
-- family's name, and every guardian's name, email and phone (digits only: "9123" finds "+65 9123 4567").  Counts come back for every filter
-- (for the current search) so the tabs can show them.  Names and phone numbers only: never money.
create or replace function public.staff_students(p_org uuid, p_q text default null, p_filter text default 'active', p_page int default 1, p_size int default 25)
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare today date := staff_students_gate(p_org); q text := nullif(trim(coalesce(p_q, '')), ''); pat text; dig text; pg int; sz int;
        res jsonb; flt text := coalesce(p_filter, 'active');
begin
  if flt not in ('active', 'ended', 'trial', 'all') then raise exception 'BAD_FILTER: unknown filter' using errcode = 'P0001'; end if;
  if q is not null and length(q) > 100 then raise exception 'BAD_SEARCH: search for at most 100 characters' using errcode = 'P0001'; end if;
  sz := least(greatest(coalesce(p_size, 25), 1), 100);
  pg := greatest(coalesce(p_page, 1), 1);
  if q is not null then
    pat := '%' || replace(replace(replace(q, '\', '\\'), '%', '\%'), '_', '\_') || '%';
    dig := nullif(regexp_replace(q, '\D', '', 'g'), '');
    -- the digits-only match is for something that LOOKS like a phone number (digits, spaces, + - and brackets, at least 3 digits); "Sec 2" is not one
    if q !~ '^[0-9+()\s-]+$' or length(coalesce(dig, '')) < 3 then dig := null; end if;
  end if;
  with matched as (
    select s.id, s.name, s.level, s.end_date, s.household_id, h.name as hname,
           (s.end_date is not null and s.end_date < today) as ended,
           exists (select 1 from lessons l where l.org_id = p_org and l.student_id = s.id and l.trial and l.lesson_date >= today - 30) as trial,
           (select count(*) from guardians gc where gc.org_id = p_org and gc.household_id = s.household_id) as gcount,
           g.name as gname, g.phone as gphone
      from students s
      left join households h on h.id = s.household_id and h.org_id = p_org
      left join lateral (select x.name, x.phone from guardians x where x.org_id = p_org and x.household_id = s.household_id order by x.created_at, x.id limit 1) g on true
     where s.org_id = p_org
       and (q is null or s.name ilike pat or s.level ilike pat or h.name ilike pat
            or exists (select 1 from guardians gg where gg.org_id = p_org and gg.household_id = s.household_id
                         and (gg.name ilike pat or gg.email ilike pat or gg.phone ilike pat
                              or (dig is not null and regexp_replace(coalesce(gg.phone, ''), '\D', '', 'g') like '%' || dig || '%'))))),
  shown as (
    select * from matched m where case flt when 'active' then not m.ended when 'ended' then m.ended when 'trial' then m.trial else true end),
  page as (select * from shown order by lower(name), id limit sz offset (pg - 1) * sz)
  select jsonb_build_object(
    'org_id', p_org, 'today', today, 'filter', flt, 'page', pg, 'size', sz,
    'total', (select count(*) from shown),
    'counts', jsonb_build_object('active', (select count(*) from matched where not ended), 'ended', (select count(*) from matched where ended),
                                 'trial', (select count(*) from matched where trial), 'all', (select count(*) from matched)),
    'rows', coalesce((select jsonb_agg(jsonb_build_object('id', p.id, 'name', p.name, 'level', p.level, 'end_date', p.end_date, 'ended', p.ended,
                       'trial', p.trial, 'household_id', p.household_id, 'household_name', p.hname,
                       'guardian_name', p.gname, 'guardian_phone', p.gphone, 'guardians', p.gcount) order by lower(p.name), p.id) from page p), '[]'::jsonb))
    into res;
  return res;
end $$;

-- ---------------------------------------------------------------- 2. one student's sheet
create or replace function public.staff_student(p_org uuid, p_student uuid) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare today date := staff_students_gate(p_org); s students; hh households; res jsonb;
begin
  select * into s from students where id = p_student and org_id = p_org;
  if not found then raise exception 'NOT_FOUND' using errcode = 'P0001'; end if;
  select * into hh from households where id = s.household_id and org_id = p_org;
  select jsonb_build_object(
    'id', s.id, 'org_id', p_org, 'name', s.name, 'level', s.level, 'notes', s.notes, 'end_date', s.end_date,
    'ended', (s.end_date is not null and s.end_date < today), 'created_at', s.created_at, 'today', today,
    'household', case when hh.id is null then null else jsonb_build_object('id', hh.id, 'name', hh.name) end,
    'guardians', coalesce((select jsonb_agg(jsonb_build_object('id', g.id, 'name', g.name, 'relation', g.relation, 'phone', g.phone, 'email', g.email)
                                            order by g.created_at, g.id) from guardians g where g.org_id = p_org and g.household_id = s.household_id), '[]'::jsonb),
    'siblings', coalesce((select jsonb_agg(jsonb_build_object('id', x.id, 'name', x.name, 'level', x.level,
                                            'ended', (x.end_date is not null and x.end_date < today)) order by lower(x.name), x.id)
                            from students x where x.org_id = p_org and x.household_id = s.household_id and x.id <> s.id), '[]'::jsonb),
    -- the subjects they are taught: what the data model has (a subject lives on the lesson and on the weekly slot, not on the student)
    'subjects', coalesce((select jsonb_agg(sj order by sj) from (
                            select distinct l.subject as sj from lessons l where l.org_id = p_org and l.student_id = s.id and nullif(trim(l.subject), '') is not null
                            union select distinct r.subject from recurring_slots r where r.org_id = p_org and r.student_id = s.id and nullif(trim(r.subject), '') is not null) u), '[]'::jsonb),
    'lessons_total', (select count(*) from lessons l where l.org_id = p_org and l.student_id = s.id),
    'lessons_trial', (select count(*) from lessons l where l.org_id = p_org and l.student_id = s.id and l.trial),
    'trial', exists (select 1 from lessons l where l.org_id = p_org and l.student_id = s.id and l.trial and l.lesson_date >= today - 30),
    -- when and who only; no price, no payment
    'next_lessons', coalesce((select jsonb_agg(jsonb_build_object('date', n.lesson_date, 'start', n.start_time, 'end', n.end_time, 'subject', n.subject,
                                            'tutor', n.tutor) order by n.lesson_date, n.start_time)
                                from (select l.lesson_date, l.start_time, l.end_time, l.subject, m.display_name as tutor
                                        from lessons l left join memberships m on m.id = l.taught_by and m.org_id = l.org_id
                                       where l.org_id = p_org and l.student_id = s.id and l.lesson_date >= today and l.status <> 'cancelled'
                                       order by l.lesson_date, l.start_time limit 5) n), '[]'::jsonb))
    into res;
  return res;
end $$;

-- ---------------------------------------------------------------- 3. add or edit (one atomic step)
-- p_student null = ADD, otherwise EDIT that student.
-- p_household: ADD only. null = a new household (the family) is created, and p_guardians (at least one) are its contacts. A household id = add a
--   sibling to that existing family (p_guardians then optional: null leaves the family's contacts as they are).  Editing never moves a student
--   to another household (merging families is out of scope).
-- p_guardians: a json array of {id?, name, relation, phone, email}. null = leave the family's contacts untouched. Otherwise it is the COMPLETE new
--   list for the household: entries with an id are updated, entries without one are added, and contacts not in the list are removed.
--   (A contact someone has linked to a parent-portal login can't be removed here.) Each needs a name and a phone or an email; at most 6.
-- p_household_name: the family's name; blank = "<student's name>'s family" for a new household, unchanged when editing.
-- Returns {student_id, household_id, created}.
create or replace function public.staff_save_student(p_org uuid, p_student uuid, p_name text, p_level text default null, p_notes text default null,
  p_household uuid default null, p_household_name text default null, p_guardians jsonb default null) returns jsonb
language plpgsql security definer set search_path = public as $$
declare today date := staff_students_gate(p_org); s students; hid uuid; nm text := nullif(trim(coalesce(p_name, '')), ''); lv text := nullif(trim(coalesce(p_level, '')), '');
        nt text := nullif(trim(coalesce(p_notes, '')), ''); hn text := nullif(trim(coalesce(p_household_name, '')), ''); owner_uid uuid; created boolean := false;
        clean jsonb := '[]'::jsonb; gj jsonb; c jsonb; gid uuid; first_g record;
begin
  -- ---- validate everything before changing anything
  if nm is null then raise exception 'BAD_STUDENT: give the student a name' using errcode = 'P0001'; end if;
  if length(nm) > 120 then raise exception 'BAD_STUDENT: the name is too long (120 characters at most)' using errcode = 'P0001'; end if;
  if lv is not null and length(lv) > 40 then raise exception 'BAD_STUDENT: the level is too long (40 characters at most)' using errcode = 'P0001'; end if;
  if nt is not null and length(nt) > 1000 then raise exception 'BAD_STUDENT: the notes are too long (1000 characters at most)' using errcode = 'P0001'; end if;
  if hn is not null and length(hn) > 120 then raise exception 'BAD_STUDENT: the family name is too long (120 characters at most)' using errcode = 'P0001'; end if;
  if p_guardians is not null then
    if jsonb_typeof(p_guardians) <> 'array' then raise exception 'BAD_GUARDIAN: guardians must be a list' using errcode = 'P0001'; end if;
    if jsonb_array_length(p_guardians) > 6 then raise exception 'BAD_GUARDIAN: at most 6 parents or guardians per family' using errcode = 'P0001'; end if;
    if jsonb_array_length(p_guardians) = 0 then raise exception 'BAD_GUARDIAN: a family needs at least one parent or guardian to contact' using errcode = 'P0001'; end if;
    for gj in select * from jsonb_array_elements(p_guardians) loop clean := clean || jsonb_build_array(staff_clean_guardian(gj)); end loop;
  end if;

  if p_student is null then                                                      -- ===================== ADD
    if p_household is null then
      if p_guardians is null then
        raise exception 'BAD_GUARDIAN: add a parent or guardian with a phone number or an email, so the centre can reach the family' using errcode = 'P0001'; end if;
    else
      if not exists (select 1 from households h where h.id = p_household and h.org_id = p_org) then raise exception 'NOT_FOUND' using errcode = 'P0001'; end if;
      if exists (select 1 from students x where x.org_id = p_org and x.household_id = p_household and lower(x.name) = lower(nm)) then
        raise exception 'DUPLICATE: % is already in this family', nm using errcode = 'P0001'; end if;
    end if;
    -- filed under the centre owner's login (see the header); the row guard needs them to be in this organisation, which an owner always is
    select m.user_id into owner_uid from memberships m where m.org_id = p_org and m.role = 'owner' and m.status = 'active' and m.user_id is not null
      order by m.created_at limit 1;
    if owner_uid is null then raise exception 'NOT_FOUND' using errcode = 'P0001'; end if;
    hid := p_household;
    if hid is null then
      insert into households(org_id, name) values (p_org, coalesce(hn, nm || '''s family')) returning id into hid;
    elsif hn is not null then
      update households set name = hn where id = hid and name is distinct from hn;
    end if;
    insert into students(tutor_id, org_id, household_id, name, level, notes) values (owner_uid, p_org, hid, nm, lv, nt) returning * into s;
    created := true;
  else                                                                           -- ===================== EDIT
    select * into s from students where id = p_student and org_id = p_org;
    if not found then raise exception 'NOT_FOUND' using errcode = 'P0001'; end if;
    if p_household is not null and p_household is distinct from s.household_id then
      raise exception 'BAD_STUDENT: moving a student to another family isn''t supported yet' using errcode = 'P0001'; end if;
    hid := s.household_id;
    if hid is null then                                                          -- an older student with no family yet: make one
      insert into households(org_id, name) values (p_org, coalesce(hn, nm || '''s family')) returning id into hid;
    elsif hn is not null then
      update households set name = hn where id = hid and org_id = p_org and name is distinct from hn;
    end if;
    update students set name = nm, level = lv, notes = nt, household_id = hid where id = s.id;
  end if;

  -- ---- the family's contacts
  if p_guardians is not null then
    -- every id must be one of THIS family's contacts (an id from somewhere else is "doesn't exist")
    for c in select * from jsonb_array_elements(clean) loop
      if c->>'id' is not null then
        begin gid := (c->>'id')::uuid; exception when others then raise exception 'NOT_FOUND' using errcode = 'P0001'; end;
        if not exists (select 1 from guardians g where g.id = gid and g.org_id = p_org and g.household_id = hid) then raise exception 'NOT_FOUND' using errcode = 'P0001'; end if;
      end if;
    end loop;
    -- contacts left out of the list are removed, unless a parent-portal login is linked to them
    if exists (select 1 from guardians g where g.org_id = p_org and g.household_id = hid and g.user_id is not null
                 and g.id::text not in (select x->>'id' from jsonb_array_elements(clean) x where x->>'id' is not null)) then
      raise exception 'BAD_GUARDIAN: a contact with a parent login can''t be removed here' using errcode = 'P0001'; end if;
    delete from guardians g where g.org_id = p_org and g.household_id = hid
       and g.id::text not in (select x->>'id' from jsonb_array_elements(clean) x where x->>'id' is not null);
    for c in select * from jsonb_array_elements(clean) loop
      if c->>'id' is not null then
        update guardians set name = c->>'name', relation = c->>'relation', phone = c->>'phone', email = c->>'email' where id = (c->>'id')::uuid;
      else
        insert into guardians(org_id, household_id, name, relation, phone, email, created_at)      -- (clock_timestamp: contacts added in one call keep their order)
        values (p_org, hid, c->>'name', c->>'relation', c->>'phone', c->>'email', clock_timestamp());
      end if;
    end loop;
  end if;

  -- ---- keep the older single-parent fields equal to the family's first contact (what tutor_my_lessons, messages and invoices still read)
  select g.name, g.phone into first_g from guardians g where g.org_id = p_org and g.household_id = hid order by g.created_at, g.id limit 1;
  update households set phone_key = org_phone_key(first_g.phone) where id = hid and phone_key is distinct from org_phone_key(first_g.phone);
  update students set contact = first_g.phone, recipient_name = first_g.name
   where org_id = p_org and household_id = hid and (contact is distinct from first_g.phone or recipient_name is distinct from first_g.name);

  insert into audit_log(org_id, actor, action, table_name, row_id, after)
  values (p_org, auth.uid(), case when created then 'staff_student_add' else 'staff_student_edit' end, 'students', s.id::text,
          jsonb_build_object('name', nm, 'level', lv, 'household_id', hid, 'guardians_replaced', p_guardians is not null));
  return jsonb_build_object('student_id', s.id, 'household_id', hid, 'created', created);
end $$;

-- ---------------------------------------------------------------- 4. discontinue / bring back
-- p_end_date = "lessons run until" (inclusive), today or earlier or later, between 2000 and 2100. null = bring the student back (clears the date).
-- Once the date has passed the student's weekly slots are switched off; bringing them back (or a date still to come) switches them on. Lessons stay.
create or replace function public.staff_set_student_end(p_org uuid, p_student uuid, p_end_date date) returns jsonb
language plpgsql security definer set search_path = public as $$
declare today date := staff_students_gate(p_org); s students; ended boolean;
begin
  select * into s from students where id = p_student and org_id = p_org;
  if not found then raise exception 'NOT_FOUND' using errcode = 'P0001'; end if;
  if p_end_date is not null and (p_end_date < date '2000-01-01' or p_end_date > date '2100-01-01') then
    raise exception 'BAD_DATE: pick a sensible date' using errcode = 'P0001'; end if;
  ended := p_end_date is not null and p_end_date < today;
  update students set end_date = p_end_date, active = not ended where id = s.id;
  update recurring_slots set active = not ended where org_id = p_org and student_id = s.id and active = ended;
  insert into audit_log(org_id, actor, action, table_name, row_id, before, after)
  values (p_org, auth.uid(), case when p_end_date is null then 'staff_student_reactivate' else 'staff_student_end' end, 'students', s.id::text,
          jsonb_build_object('end_date', s.end_date), jsonb_build_object('end_date', p_end_date));
  return jsonb_build_object('student_id', s.id, 'end_date', p_end_date, 'ended', ended);
end $$;

-- ---------------------------------------------------------------- who may call what
-- The four screens' functions: signed-in users only (each one checks the person itself). The gate and the contact cleaner are internal.
revoke all on function public.staff_students(uuid, text, text, int, int) from public, anon;
revoke all on function public.staff_student(uuid, uuid) from public, anon;
revoke all on function public.staff_save_student(uuid, uuid, text, text, text, uuid, text, jsonb) from public, anon;
revoke all on function public.staff_set_student_end(uuid, uuid, date) from public, anon;
grant execute on function public.staff_students(uuid, text, text, int, int) to authenticated;
grant execute on function public.staff_student(uuid, uuid) to authenticated;
grant execute on function public.staff_save_student(uuid, uuid, text, text, text, uuid, text, jsonb) to authenticated;
grant execute on function public.staff_set_student_end(uuid, uuid, date) to authenticated;
revoke all on function public.staff_students_gate(uuid) from public, anon, authenticated;
revoke all on function public.staff_clean_guardian(jsonb) from public, anon, authenticated;

-- #####################################################################################################
-- ### PART 3 of 21 — centre attendance + guard
-- ### source branch: claude/t3-3-attendance   file: db/migration_staff_attendance.sql   undo: db/migration_staff_attendance_down.sql
-- ### (if an error appears, search this file for the nearest "### PART" line above the error line: that is the part that failed)
-- #####################################################################################################
-- =====================================================================================================
-- T3 step 3 — centre Attendance for owners and staff: view, mark, correct        undo: migration_staff_attendance_down.sql
-- =====================================================================================================
-- Needs migration_org_foundation.sql, migration_attendance.sql and migration_tutor_access.sql (lessons.attendance, taught_by, the stamp trigger).
-- ADD-ONLY: one new trigger on `lessons` and four new functions; no table or column is touched.
--
-- PART 1 — CLOSING THE INTEGRITY HOLE (the rules now live in the table, so they hold for EVERY writer)
--   Until now "not before the lesson's day" and "never over someone else's mark" were only checked inside tutor_mark_attendance. Staff and
--   owners write `lessons` straight through the org_write policy, so a script or a copy of the app could mark tomorrow's lesson, or overwrite a
--   tutor's mark, and nobody would be asked why. The trigger lessons_attendance_guard (centres only) now refuses, for anyone signed in:
--     * setting attendance on a lesson whose day (in the CENTRE's timezone) hasn't started        → TOO_EARLY
--     * changing or clearing a mark that somebody ELSE made                                        → ALREADY_MARKED
--     * editing attendance_marked_by / attendance_marked_at on their own (a back door to the rule above) → LOCKED
--   The ONE way past the second and third rule is staff_correct_attendance(), which sets a transaction-local flag naming that one lesson
--   (td.attendance_override = the lesson id, like td.deleting_org) after checking permission and a written reason. "Too early" has NO way
--   past, not even for the function. Solo tutors' lessons never reach the guard (it returns at once unless the lesson's organisation is a
--   centre) and server jobs with no signed-in user (auth.uid() is null: billing, the account-deletion function) are not "someone marking".
--
-- PART 2 — WHAT STAFF CAN DO (decided by the owner, 2026-11-25)
--   staff_lessons(org, from, to, tutor, status, page, size)   the list for a day or a week (at most 62 days), filters, server-side paging.
--                                                             Any owner / staff member may LOOK. Returns NO money (no rate, amount, paid,
--                                                             compensation or *_cents), only the yes/no "charge pending".
--   staff_mark_attendance(lesson, attendance, remarks)        first mark of a lesson, from its day onward. Needs manage_timetable.
--   staff_correct_attendance(lesson, attendance, reason)      change a mark somebody already made. Needs manage_timetable AND a written
--                                                             reason; writes a named audit entry with the reason. Tutors never.
--   * Staff can ALWAYS mark and correct. lessons.attendance_by (tutor | admin), attendance_window_days and cancellations_marked_by only
--     govern TUTORS (tutor_mark_attendance); they are not consulted here. Staff may set all four values, including both cancellations.
--   * Status follows attendance, set by the existing stamp trigger (never typed): attended = done; absent / cancelled_early / late_cancelled =
--     cancelled. The charge for an absent / cancelled lesson is its COMPENSATION: a number someone types, 0 if the family isn't charged,
--     null = "charge pending". THIS step never types it (that is step 4); marking absent leaves it null, marking attended clears it.
--     lessons.compensation_entered_by (admin | tutor) only decides who types it later; billing.absences.mode only pre-fills the suggestion later.
--   * lessons.remarks.required is the centre's rule for marking ATTENDED (same words as for tutors). Correcting an old mark does not re-require remarks.
--   * A lesson cancelled by staff with no attendance mark is CLOSED: it can't be marked (same as the tutor function).
--   * Nothing needs a class, a room or a branch: a remote 1-to-1 centre marks lessons with just a student and a time.
--
-- WHO MAY CALL
--   not a member / a tutor / a parent / switched-off staff / a solo organisation / an unknown id  → NOT_FOUND (same words for all, so ids can't be probed)
--   staff WITHOUT manage_timetable (look only)                                                   → NOT_ALLOWED when they try to mark or correct
-- Run on the DEV project first. Safe to run twice.
-- =====================================================================================================

-- ---------------------------------------------------------------- PART 1: the guard
create or replace function public.lessons_attendance_guard() returns trigger
language plpgsql security definer set search_path = public as $$
declare me uuid := auth.uid(); tz text; today date; override boolean;
begin
  if me is null then return new; end if;                                   -- server jobs, not a person marking
  select o.timezone into tz from organisations o where o.id = new.org_id and o.kind = 'centre';
  if tz is null then return new; end if;                                   -- solo tutors' lessons: nothing changes
  today := (now() at time zone tz)::date;                                  -- the centre's own calendar day, not the server's
  override := coalesce(current_setting('td.attendance_override', true), '') = new.id::text;

  if tg_op = 'INSERT' then
    if new.attendance is not null and new.lesson_date > today then
      raise exception 'TOO_EARLY: a lesson can be marked from its day onward' using errcode = 'P0001'; end if;
    return new;
  end if;

  if new.attendance is not distinct from old.attendance then
    -- the stamp columns are the proof of who marked; they change only together with the mark (the stamp trigger) or by a correction
    if (new.attendance_marked_by is distinct from old.attendance_marked_by or new.attendance_marked_at is distinct from old.attendance_marked_at)
       and not override then
      raise exception 'LOCKED: who marked a lesson and when can''t be edited by hand' using errcode = 'P0001'; end if;
    return new;
  end if;

  if new.attendance is not null and new.lesson_date > today then
    raise exception 'TOO_EARLY: a lesson can be marked from its day onward' using errcode = 'P0001'; end if;
  if old.attendance is not null and old.attendance_marked_by is distinct from me and not override then
    raise exception 'ALREADY_MARKED: someone else already marked this lesson; use Correct (with a reason) to change it' using errcode = 'P0001'; end if;
  return new;
end $$;
-- fires BEFORE the stamp trigger (triggers run in name order), so it sees what the writer asked for, not what the stamp then fills in
drop trigger if exists lessons_attendance_guard on public.lessons;
create trigger lessons_attendance_guard
  before insert or update of attendance, attendance_marked_by, attendance_marked_at on public.lessons
  for each row execute function public.lessons_attendance_guard();

-- ---------------------------------------------------------------- the gate every staff attendance function starts with (internal)
-- Returns the centre's own "today". p_write = the caller must also hold manage_timetable.
create or replace function public.staff_attendance_gate(p_org uuid, p_write boolean) returns date
language plpgsql stable security definer set search_path = public as $$
declare tz text;
begin
  if auth.uid() is null then raise exception 'NOT_FOUND' using errcode = 'P0001'; end if;
  select o.timezone into tz from organisations o where o.id = p_org and o.kind = 'centre';
  if tz is null or not exists (select 1 from memberships m where m.org_id = p_org and m.user_id = auth.uid() and m.status = 'active'
                               and m.role in ('owner', 'staff')) then
    raise exception 'NOT_FOUND' using errcode = 'P0001';
  end if;
  if p_write and not org_can(p_org, 'manage_timetable') then
    raise exception 'NOT_ALLOWED: your account can''t mark attendance at this centre' using errcode = '42501';
  end if;
  return (now() at time zone tz)::date;
end $$;

-- ---------------------------------------------------------------- PART 2a: the list
-- p_status: 'all' | 'unmarked' (due: its day has started, not cancelled by staff, no mark) | 'marked'. p_tutor: a memberships.id, or null for everyone.
-- state of a row: 'future' (its day hasn't started: no buttons) | 'open' (can be marked) | 'marked' (can be corrected) | 'cancelled' (closed by staff).
-- can_mark / can_correct already include the caller's permission, so the screen doesn't guess.
create or replace function public.staff_lessons(p_org uuid, p_from date, p_to date, p_tutor uuid default null,
                                                p_status text default 'all', p_page int default 1, p_size int default 50) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare today date := staff_attendance_gate(p_org, false); can_tt boolean := org_can(p_org, 'manage_timetable');
        st text := coalesce(nullif(p_status, ''), 'all'); pg int := coalesce(p_page, 1); sz int := coalesce(p_size, 50);
        total int; cnt jsonb; rows jsonb; tutors jsonb;
begin
  if p_from is null or p_to is null or p_to < p_from or p_to - p_from > 62 then
    raise exception 'BAD_RANGE: ask for at most 62 days' using errcode = 'P0001'; end if;
  if st not in ('all', 'unmarked', 'marked') then raise exception 'BAD_FILTER: unknown filter' using errcode = 'P0001'; end if;
  if pg < 1 or pg > 100000 then raise exception 'BAD_PAGE: no such page' using errcode = 'P0001'; end if;
  if sz < 1 or sz > 100 then raise exception 'BAD_PAGE: ask for 1 to 100 lessons at a time' using errcode = 'P0001'; end if;
  if p_tutor is not null and not exists (select 1 from memberships m where m.id = p_tutor and m.org_id = p_org) then
    raise exception 'NOT_FOUND' using errcode = 'P0001'; end if;

  with base as (
    select l.id, l.lesson_date, l.start_time, l.end_time, l.subject, l.status, l.attendance, l.trial, l.remarks, l.session_id,
           l.attendance_marked_at, l.taught_by, (l.compensation is null) as no_comp,
           s.id as sid, s.name as sname, s.level as slevel, t.display_name as tname, mb.display_name as mname,
           (l.status = 'cancelled' and l.attendance is null) as closed,
           (l.attendance is null and l.status <> 'cancelled' and l.lesson_date <= today) as due
      from lessons l
      join students s on s.id = l.student_id and s.org_id = l.org_id
      left join memberships t  on t.id = l.taught_by and t.org_id = l.org_id
      left join memberships mb on mb.user_id = l.attendance_marked_by and mb.org_id = l.org_id
     where l.org_id = p_org and l.lesson_date between p_from and p_to and (p_tutor is null or l.taught_by = p_tutor)),
  d as (
    select base.*, case when closed then 'cancelled' when attendance is not null then 'marked' when lesson_date > today then 'future' else 'open' end as state
      from base),
  c as (select count(*)::int as n_all, (count(*) filter (where due))::int as n_unmarked, (count(*) filter (where attendance is not null))::int as n_marked from d),
  pg_rows as (
    select * from d
     where st = 'all' or (st = 'unmarked' and due) or (st = 'marked' and attendance is not null)
     order by lesson_date, start_time, sname, id
     limit sz offset (pg - 1) * sz)
  select (select row_to_json(c) from c)::jsonb,
         coalesce((select jsonb_agg(jsonb_build_object(
           'lesson_id', id, 'lesson_date', lesson_date, 'start_time', start_time, 'end_time', end_time,
           'student_id', sid, 'student_name', sname, 'student_level', slevel, 'subject', subject,
           'tutor_id', taught_by, 'tutor_name', tname,
           'attendance', attendance, 'status', status, 'state', state, 'trial', trial, 'remarks', remarks,
           'marked_at', attendance_marked_at, 'marked_by_name', mname,
           'charge_pending', (attendance in ('absent', 'cancelled_early', 'late_cancelled') and no_comp),
           'session_id', session_id,
           'can_mark', (can_tt and state = 'open'), 'can_correct', (can_tt and state = 'marked'))
           order by lesson_date, start_time, sname, id) from pg_rows), '[]'::jsonb)
    into cnt, rows;

  total := case st when 'unmarked' then (cnt->>'n_unmarked')::int when 'marked' then (cnt->>'n_marked')::int else (cnt->>'n_all')::int end;
  select coalesce(jsonb_agg(jsonb_build_object('id', m.id, 'name', m.display_name) order by m.display_name, m.id), '[]'::jsonb) into tutors
    from memberships m where m.org_id = p_org and m.role = 'tutor' and m.status in ('active', 'invited');

  return jsonb_build_object('today', today, 'can_mark', can_tt, 'page', pg, 'size', sz, 'total', total,
                            'counts', jsonb_build_object('all', (cnt->>'n_all')::int, 'unmarked', (cnt->>'n_unmarked')::int,
                                                         'marked', (cnt->>'n_marked')::int),
                            'tutors', tutors, 'rows', rows);
end $$;

-- ---------------------------------------------------------------- PART 2b: the first mark
create or replace function public.staff_mark_attendance(p_lesson uuid, p_attendance text, p_remarks text default null) returns jsonb
language plpgsql security definer set search_path = public as $$
declare l lessons; cfg jsonb; today date; new_remarks text; new_status text;
begin
  if auth.uid() is null then raise exception 'NOT_FOUND' using errcode = 'P0001'; end if;
  select * into l from lessons where id = p_lesson;
  if not found then raise exception 'NOT_FOUND' using errcode = 'P0001'; end if;
  today := staff_attendance_gate(l.org_id, true);
  cfg := org_settings_on(l.org_id, current_date);

  if p_attendance is null or p_attendance not in ('attended', 'absent', 'late_cancelled', 'cancelled_early') then
    raise exception 'BAD_VALUE: choose attended, absent, late cancelled or cancelled in time' using errcode = 'P0001'; end if;
  if l.status = 'cancelled' and l.attendance is null then
    raise exception 'CANCELLED: this lesson was cancelled' using errcode = 'P0001'; end if;
  if l.attendance is not null then
    raise exception 'ALREADY_MARKED: this lesson is already marked; use Correct (with a reason) to change it' using errcode = 'P0001'; end if;
  if l.lesson_date > today then
    raise exception 'TOO_EARLY: a lesson can be marked from its day onward' using errcode = 'P0001'; end if;
  if length(coalesce(p_remarks, '')) > 2000 then
    raise exception 'TOO_LONG: keep the remarks under 2000 characters' using errcode = 'P0001'; end if;

  new_remarks := case when p_remarks is null then l.remarks else nullif(trim(p_remarks), '') end;
  -- the centre's own rule: a lesson that took place needs its remarks
  if p_attendance = 'attended' and coalesce((cfg #>> '{lessons,remarks,required}')::boolean, false) and new_remarks is null then
    raise exception 'REMARKS_REQUIRED: this centre needs remarks before a lesson is marked attended' using errcode = 'P0001'; end if;

  update lessons set attendance = p_attendance, remarks = new_remarks,
                     remarks_at = case when p_remarks is null then remarks_at else now() end
   where id = l.id returning status into new_status;

  insert into audit_log(org_id, actor, action, table_name, row_id, after)
  values (l.org_id, auth.uid(), 'staff_mark_attendance', 'lessons', l.id::text,
          jsonb_build_object('attendance', p_attendance, 'status', new_status, 'remarks_set', p_remarks is not null));
  return jsonb_build_object('lesson_id', l.id, 'attendance', p_attendance, 'status', new_status);
end $$;

-- ---------------------------------------------------------------- PART 2c: the correction (the only way over someone else's mark)
create or replace function public.staff_correct_attendance(p_lesson uuid, p_attendance text, p_reason text) returns jsonb
language plpgsql security definer set search_path = public as $$
declare l lessons; today date; why text := nullif(trim(coalesce(p_reason, '')), ''); new_status text;
begin
  if auth.uid() is null then raise exception 'NOT_FOUND' using errcode = 'P0001'; end if;
  select * into l from lessons where id = p_lesson;
  if not found then raise exception 'NOT_FOUND' using errcode = 'P0001'; end if;
  today := staff_attendance_gate(l.org_id, true);

  if p_attendance is null or p_attendance not in ('attended', 'absent', 'late_cancelled', 'cancelled_early') then
    raise exception 'BAD_VALUE: choose attended, absent, late cancelled or cancelled in time' using errcode = 'P0001'; end if;
  if why is null then raise exception 'REASON_REQUIRED: say why you are changing this mark' using errcode = 'P0001'; end if;
  if length(why) > 500 then raise exception 'TOO_LONG: keep the reason under 500 characters' using errcode = 'P0001'; end if;
  if l.attendance is null then
    raise exception 'NOT_MARKED: this lesson hasn''t been marked yet; mark it instead' using errcode = 'P0001'; end if;
  if l.attendance = p_attendance then
    raise exception 'NO_CHANGE: the lesson is already marked that way' using errcode = 'P0001'; end if;
  if l.lesson_date > today then
    raise exception 'TOO_EARLY: a lesson can be marked from its day onward' using errcode = 'P0001'; end if;

  -- the flag names THIS lesson only and lasts for this transaction; the guard still refuses "too early" even with it
  perform set_config('td.attendance_override', l.id::text, true);
  update lessons set attendance = p_attendance where id = l.id returning status into new_status;
  perform set_config('td.attendance_override', '', true);

  insert into audit_log(org_id, actor, action, table_name, row_id, before, after)
  values (l.org_id, auth.uid(), 'staff_correct_attendance', 'lessons', l.id::text,
          jsonb_build_object('attendance', l.attendance, 'status', l.status, 'marked_by', l.attendance_marked_by, 'marked_at', l.attendance_marked_at),
          jsonb_build_object('attendance', p_attendance, 'status', new_status, 'reason', why));
  return jsonb_build_object('lesson_id', l.id, 'attendance', p_attendance, 'status', new_status);
end $$;

-- ---------------------------------------------------------------- who may call what
revoke all on function public.staff_lessons(uuid, date, date, uuid, text, int, int) from public, anon;
revoke all on function public.staff_mark_attendance(uuid, text, text) from public, anon;
revoke all on function public.staff_correct_attendance(uuid, text, text) from public, anon;
grant execute on function public.staff_lessons(uuid, date, date, uuid, text, int, int) to authenticated;
grant execute on function public.staff_mark_attendance(uuid, text, text) to authenticated;
grant execute on function public.staff_correct_attendance(uuid, text, text) to authenticated;
revoke all on function public.staff_attendance_gate(uuid, boolean) from public, anon, authenticated;
revoke all on function public.lessons_attendance_guard() from public, anon, authenticated;

-- #####################################################################################################
-- ### PART 4 of 21 — pending charges for absent / cancelled lessons
-- ### source branch: claude/t3-4-charges   file: db/migration_staff_charges.sql   undo: db/migration_staff_charges_down.sql
-- ### (if an error appears, search this file for the nearest "### PART" line above the error line: that is the part that failed)
-- #####################################################################################################
-- =====================================================================================================
-- T3 step 4 — centre Pending charges for owners and staff                          undo: migration_staff_charges_down.sql
-- =====================================================================================================
-- Needs migration_org_foundation.sql, migration_attendance.sql, migration_tutor_access.sql and migration_staff_attendance.sql.
-- ADD-ONLY: five new functions; no table, column, policy or trigger is touched. Nothing here creates an invoice (that is T4).
--
-- THE MODEL (unchanged, owner's rule): an absent / cancelled lesson becomes status 'cancelled' and its billable amount is its COMPENSATION,
-- a number someone types: 0 = the family isn't charged, null = "charge pending" (invoicing must wait for it). `lessons.compensation` is
-- numeric DOLLARS (it always was); `compensation_cents` is the generated whole-cents twin. These functions speak INTEGER CENTS at the edge
-- (as assets/js/money.js does) and store cents / 100 exactly, so the two columns can never disagree.
--
-- WHO MAY CALL (owner's decision, 2026-11-25): an active OWNER, or STAFF holding `issue_invoices`. NOT manage_timetable: a receptionist who marks
-- attendance can't set what a family pays. A tutor, a parent, switched-off staff, a stranger, a solo organisation and an unknown id all get
-- the same NOT_FOUND; staff without issue_invoices get NOT_ALLOWED in plain words.
--
-- THE QUEUE = lessons whose attendance is absent / cancelled_early / late_cancelled and whose compensation is null. (The same rule as the
-- "charges to confirm" number on the centre Home.) Which of the two settings puts a lesson in the queue:
--   lessons.compensation_entered_by = admin   (default) every absent / cancelled lesson waits here, whoever marked it
--   lessons.compensation_entered_by = tutor   the tutor must type the charge when marking (CHARGE_REQUIRED, existing tutor function), so the
--                                             queue holds only lessons STAFF marked and old ones. Staff may always type or change a charge
--                                             here, whatever the setting (they are the safety net); changing a charge that already has a
--                                             number needs a written reason.
-- billing.absences.mode only PRE-FILLS a suggestion; a person always confirms (owner's decision). It is a MONEY rule, so it is read as of the
-- lesson's own day (org_settings_on(org, lesson_date)), not as of today (if no version existed yet that day, today's is used):
--   charged                 suggest the full price for absent, late cancelled and cancelled in time
--   not_charged             suggest 0
--   charged_unless_notice   suggest 0 for "cancelled in time" (that mark already means enough notice was given), the full price otherwise
--   (billing.absences.notice_hours is not re-computed: staff choose "cancelled in time" or "late cancelled" when they mark.)
--
-- RULES THAT NEVER BEND: the amount is a whole number of cents from 0 up to the lesson's own price (amount, else rate × hours); only an
-- absent / cancelled lesson has a charge; a paid lesson's charge is locked; every change writes a named audit entry (who, when, before, after).
-- Run on the DEV project first. Safe to run twice.
-- =====================================================================================================

-- ---------------------------------------------------------------- the gate every charge function starts with (internal)
create or replace function public.staff_charges_gate(p_org uuid) returns date
language plpgsql stable security definer set search_path = public as $$
declare tz text;
begin
  if auth.uid() is null then raise exception 'NOT_FOUND' using errcode = 'P0001'; end if;
  select o.timezone into tz from organisations o where o.id = p_org and o.kind = 'centre';
  if tz is null or not exists (select 1 from memberships m where m.org_id = p_org and m.user_id = auth.uid() and m.status = 'active'
                               and m.role in ('owner', 'staff')) then
    raise exception 'NOT_FOUND' using errcode = 'P0001';
  end if;
  if not org_can(p_org, 'issue_invoices') then
    raise exception 'NOT_ALLOWED: your account can''t set charges at this centre' using errcode = '42501';
  end if;
  return (now() at time zone tz)::date;
end $$;

-- ---------------------------------------------------------------- the lesson's own price in cents (internal, pure)
-- amount when set, else rate × hours; the same rule as tutor_mark_attendance; never null.
create or replace function public.lesson_price_cents(p_amount numeric, p_rate numeric, p_start time, p_end time) returns bigint
language sql immutable set search_path = public as $$
  select coalesce(round(nullif(p_amount, 0) * 100)::bigint,
                  round(p_rate * extract(epoch from (p_end - p_start)) / 3600 * 100)::bigint, 0)
$$;

-- ---------------------------------------------------------------- the suggestion from billing.absences.mode (internal, pure)
create or replace function public.charge_suggestion_cents(p_mode text, p_attendance text, p_price bigint) returns bigint
language sql immutable set search_path = public as $$
  select case p_mode
           when 'charged'               then p_price
           when 'not_charged'           then 0
           when 'charged_unless_notice' then case when p_attendance = 'cancelled_early' then 0 else p_price end
         end
$$;

-- ---------------------------------------------------------------- how many charges are waiting (for Home, and for T4: "not ready to invoice")
create or replace function public.pending_charge_count(p_org uuid) returns int
language plpgsql stable security definer set search_path = public as $$
declare n int;
begin
  perform staff_charges_gate(p_org);
  select count(*)::int into n from lessons l
   where l.org_id = p_org and l.attendance in ('absent', 'cancelled_early', 'late_cancelled') and l.compensation is null;
  return n;
end $$;

-- ---------------------------------------------------------------- the queue
-- Newest first, 1..100 per page. Staff with issue_invoices see the lesson's price (that is the point); tutors never reach this.
create or replace function public.staff_pending_charges(p_org uuid, p_page int default 1, p_size int default 50) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare today date := staff_charges_gate(p_org); pg int := coalesce(p_page, 1); sz int := coalesce(p_size, 50); total int; rows jsonb;
begin
  if pg < 1 or pg > 100000 then raise exception 'BAD_PAGE: no such page' using errcode = 'P0001'; end if;
  if sz < 1 or sz > 100 then raise exception 'BAD_PAGE: ask for 1 to 100 lessons at a time' using errcode = 'P0001'; end if;

  select count(*)::int into total from lessons l
   where l.org_id = p_org and l.attendance in ('absent', 'cancelled_early', 'late_cancelled') and l.compensation is null;

  select coalesce(jsonb_agg(jsonb_build_object(
           'lesson_id', q.id, 'lesson_date', q.lesson_date, 'start_time', q.start_time, 'end_time', q.end_time,
           'student_id', q.sid, 'student_name', q.sname, 'student_level', q.slevel, 'subject', q.subject,
           'tutor_name', q.tname, 'attendance', q.attendance, 'remarks', q.remarks,
           'marked_by_name', q.mname, 'marked_at', q.attendance_marked_at, 'session_id', q.session_id,
           'price_cents', q.price, 'suggestion_mode', q.mode,
           'suggested_cents', charge_suggestion_cents(q.mode, q.attendance, q.price))
           order by q.lesson_date desc, q.start_time desc, q.sname, q.id), '[]'::jsonb)
    into rows
    from (select l.id, l.lesson_date, l.start_time, l.end_time, l.subject, l.attendance, l.remarks, l.session_id, l.attendance_marked_at,
                 s.id as sid, s.name as sname, s.level as slevel, t.display_name as tname, mb.display_name as mname,
                 lesson_price_cents(l.amount, l.rate, l.start_time, l.end_time) as price,
                 coalesce(org_settings_on(p_org, l.lesson_date) #>> '{billing,absences,mode}',      -- the rule in force that day,
                          org_settings_on(p_org, today) #>> '{billing,absences,mode}') as mode          -- else today's (no version existed yet)
            from lessons l
            join students s on s.id = l.student_id and s.org_id = l.org_id
            left join memberships t  on t.id = l.taught_by and t.org_id = l.org_id
            left join memberships mb on mb.user_id = l.attendance_marked_by and mb.org_id = l.org_id
           where l.org_id = p_org and l.attendance in ('absent', 'cancelled_early', 'late_cancelled') and l.compensation is null
           order by l.lesson_date desc, l.start_time desc, s.name, l.id
           limit sz offset (pg - 1) * sz) q;

  return jsonb_build_object('today', today, 'page', pg, 'size', sz, 'total', total, 'rows', rows);
end $$;

-- ---------------------------------------------------------------- one charge
-- p_amount_cents: whole cents, 0 = the family isn't charged. p_reason: required only when the lesson ALREADY has a charge (a change).
create or replace function public.staff_set_charge(p_lesson uuid, p_amount_cents bigint, p_reason text default null) returns jsonb
language plpgsql security definer set search_path = public as $$
declare l lessons; price bigint; old_c bigint; why text := nullif(trim(coalesce(p_reason, '')), '');
begin
  if auth.uid() is null then raise exception 'NOT_FOUND' using errcode = 'P0001'; end if;
  select * into l from lessons where id = p_lesson for update;
  if not found then raise exception 'NOT_FOUND' using errcode = 'P0001'; end if;
  perform staff_charges_gate(l.org_id);

  if l.attendance is null or l.attendance not in ('absent', 'cancelled_early', 'late_cancelled') then
    raise exception 'NOT_CANCELLED: only a lesson marked absent or cancelled has a charge' using errcode = 'P0001'; end if;
  price := lesson_price_cents(l.amount, l.rate, l.start_time, l.end_time);
  if p_amount_cents is null or p_amount_cents < 0 or p_amount_cents > price then
    raise exception 'BAD_CHARGE: enter an amount from 0 up to the lesson''s own price (S$%)', to_char(price / 100.0, 'FM999999990.00') using errcode = 'P0001'; end if;
  if l.paid then raise exception 'ALREADY_PAID: this lesson is already paid, so its charge can''t be changed' using errcode = 'P0001'; end if;

  old_c := l.compensation_cents;
  if old_c is not null then
    if old_c = p_amount_cents then raise exception 'NO_CHANGE: the charge is already that amount' using errcode = 'P0001'; end if;
    if why is null then raise exception 'REASON_REQUIRED: this lesson already has a charge; say why you are changing it' using errcode = 'P0001'; end if;
  end if;
  if length(coalesce(why, '')) > 500 then raise exception 'TOO_LONG: keep the reason under 500 characters' using errcode = 'P0001'; end if;

  update lessons set compensation = p_amount_cents / 100.0 where id = l.id;

  insert into audit_log(org_id, actor, action, table_name, row_id, before, after)
  values (l.org_id, auth.uid(), 'staff_set_charge', 'lessons', l.id::text,
          jsonb_build_object('compensation_cents', old_c, 'attendance', l.attendance),
          jsonb_build_object('compensation_cents', p_amount_cents, 'price_cents', price, 'reason', why));
  return jsonb_build_object('lesson_id', l.id, 'compensation_cents', p_amount_cents, 'price_cents', price);
end $$;

-- ---------------------------------------------------------------- many charges at once (only lessons still waiting for one)
-- p_mode 'amount': the SAME amount for each (p_amount_cents, 0 = not charged; it may not exceed ANY of the lessons' own prices)
-- p_mode 'full'  : each lesson's own price. All or nothing: one problem and nothing is saved.
create or replace function public.staff_set_charges(p_lessons uuid[], p_mode text, p_amount_cents bigint default null) returns jsonb
language plpgsql security definer set search_path = public as $$
declare ids uuid[]; org uuid; n int; r record; price bigint; amt bigint; done int := 0; total bigint := 0;
begin
  if auth.uid() is null then raise exception 'NOT_FOUND' using errcode = 'P0001'; end if;
  if p_mode is null or p_mode not in ('amount', 'full') then raise exception 'BAD_VALUE: choose a charge' using errcode = 'P0001'; end if;
  select coalesce(array_agg(distinct x), '{}') into ids from unnest(coalesce(p_lessons, '{}')) x where x is not null;
  n := coalesce(array_length(ids, 1), 0);
  if n = 0 then raise exception 'BAD_VALUE: choose at least one lesson' using errcode = 'P0001'; end if;
  if n > 100 then raise exception 'TOO_MANY: choose up to 100 lessons at a time' using errcode = 'P0001'; end if;

  -- every id must exist and all must belong to ONE centre (anything else: the same NOT_FOUND, so ids can't be probed)
  select (array_agg(l.org_id))[1] into org from lessons l where l.id = any(ids);
  if (select count(*) from lessons l where l.id = any(ids)) <> n or (select count(distinct l.org_id) from lessons l where l.id = any(ids)) <> 1 then
    raise exception 'NOT_FOUND' using errcode = 'P0001'; end if;
  perform staff_charges_gate(org);

  if p_mode = 'amount' and (p_amount_cents is null or p_amount_cents < 0) then
    raise exception 'BAD_CHARGE: enter an amount of 0 or more' using errcode = 'P0001'; end if;

  -- lock them in a fixed order, then check every one before writing any
  for r in select l.* from lessons l where l.id = any(ids) order by l.id for update loop
    if r.attendance is null or r.attendance not in ('absent', 'cancelled_early', 'late_cancelled') then
      raise exception 'NOT_CANCELLED: only a lesson marked absent or cancelled has a charge' using errcode = 'P0001'; end if;
    if r.compensation is not null then
      raise exception 'ALREADY_SET: someone has already set the charge for one of these lessons. Refresh the list and try again' using errcode = 'P0001'; end if;
    if r.paid then raise exception 'ALREADY_PAID: one of these lessons is already paid' using errcode = 'P0001'; end if;
    price := lesson_price_cents(r.amount, r.rate, r.start_time, r.end_time);
    if p_mode = 'amount' and p_amount_cents > price then
      raise exception 'BAD_CHARGE: that amount is more than one of these lessons costs (S$%). Choose "Charge full price" or a smaller amount', to_char(price / 100.0, 'FM999999990.00') using errcode = 'P0001'; end if;
  end loop;

  for r in select l.* from lessons l where l.id = any(ids) order by l.id loop
    price := lesson_price_cents(r.amount, r.rate, r.start_time, r.end_time);
    amt := case p_mode when 'full' then price else p_amount_cents end;
    update lessons set compensation = amt / 100.0 where id = r.id;
    insert into audit_log(org_id, actor, action, table_name, row_id, before, after)
    values (r.org_id, auth.uid(), 'staff_set_charge', 'lessons', r.id::text,
            jsonb_build_object('compensation_cents', null, 'attendance', r.attendance),
            jsonb_build_object('compensation_cents', amt, 'price_cents', price, 'bulk', n, 'mode', p_mode));
    done := done + 1; total := total + amt;
  end loop;
  return jsonb_build_object('updated', done, 'total_cents', total);
end $$;

-- ---------------------------------------------------------------- who may call what
revoke all on function public.staff_pending_charges(uuid, int, int) from public, anon;
revoke all on function public.staff_set_charge(uuid, bigint, text) from public, anon;
revoke all on function public.staff_set_charges(uuid[], text, bigint) from public, anon;
revoke all on function public.pending_charge_count(uuid) from public, anon;
grant execute on function public.staff_pending_charges(uuid, int, int) to authenticated;
grant execute on function public.staff_set_charge(uuid, bigint, text) to authenticated;
grant execute on function public.staff_set_charges(uuid[], text, bigint) to authenticated;
grant execute on function public.pending_charge_count(uuid) to authenticated;
revoke all on function public.staff_charges_gate(uuid) from public, anon, authenticated;
revoke all on function public.lesson_price_cents(numeric, numeric, time, time) from public, anon, authenticated;
revoke all on function public.charge_suggestion_cents(text, text, bigint) from public, anon, authenticated;

-- #####################################################################################################
-- ### PART 5 of 21 — trial flag
-- ### source branch: claude/t3-5-trials   file: db/migration_staff_trials.sql   undo: db/migration_staff_trials_down.sql
-- ### (if an error appears, search this file for the nearest "### PART" line above the error line: that is the part that failed)
-- #####################################################################################################
-- =====================================================================================================
-- T3 step 5 — the Trial flag for owners and staff                                 undo: migration_staff_trials_down.sql
-- =====================================================================================================
-- Needs migration_staff_attendance.sql (staff_attendance_gate, staff_lessons). Changes: ONE new function, and staff_lessons is
-- re-created with the same signature so its status filter also accepts 'trial' and its counts gain a 'trial' number. No table, column,
-- policy or trigger is touched.
--
--   staff_set_trial(lesson, trial)   flag or unflag ONE lesson as a trial lesson. Needs manage_timetable (the same permission as marking),
--                                    owners always. Staff can ALWAYS do it: lessons.trials_flagged_by (admin | tutor) only decides whether
--                                    TUTORS may (tutor_mark_attendance, unchanged). Writes a named audit entry: who, when, before, after.
--   A trial lesson does not count towards the centre's fee: org_active_students_in_month() (migration_attendance.sql, unchanged) only
--   counts students with at least one NON-trial lesson marked attended / absent / late cancelled that month. So flagging a student's only
--   lesson of the month takes them out of that month's count, and unflagging puts them back. Nothing here recomputes a fee that was
--   already worked out for a past month (the screen says so).
-- Who may call: not a member / tutor / parent / switched-off staff / solo organisation / unknown id → NOT_FOUND (same words for all);
-- staff WITHOUT manage_timetable → NOT_ALLOWED.
-- Run on the DEV project first. Safe to run twice.
-- =====================================================================================================

-- ---------------------------------------------------------------- the list gains a Trial filter and a trial count
create or replace function public.staff_lessons(p_org uuid, p_from date, p_to date, p_tutor uuid default null,
                                                p_status text default 'all', p_page int default 1, p_size int default 50) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare today date := staff_attendance_gate(p_org, false); can_tt boolean := org_can(p_org, 'manage_timetable');
        st text := coalesce(nullif(p_status, ''), 'all'); pg int := coalesce(p_page, 1); sz int := coalesce(p_size, 50);
        total int; cnt jsonb; rows jsonb; tutors jsonb;
begin
  if p_from is null or p_to is null or p_to < p_from or p_to - p_from > 62 then
    raise exception 'BAD_RANGE: ask for at most 62 days' using errcode = 'P0001'; end if;
  if st not in ('all', 'unmarked', 'marked', 'trial') then raise exception 'BAD_FILTER: unknown filter' using errcode = 'P0001'; end if;
  if pg < 1 or pg > 100000 then raise exception 'BAD_PAGE: no such page' using errcode = 'P0001'; end if;
  if sz < 1 or sz > 100 then raise exception 'BAD_PAGE: ask for 1 to 100 lessons at a time' using errcode = 'P0001'; end if;
  if p_tutor is not null and not exists (select 1 from memberships m where m.id = p_tutor and m.org_id = p_org) then
    raise exception 'NOT_FOUND' using errcode = 'P0001'; end if;

  with base as (
    select l.id, l.lesson_date, l.start_time, l.end_time, l.subject, l.status, l.attendance, l.trial, l.remarks, l.session_id,
           l.attendance_marked_at, l.taught_by, (l.compensation is null) as no_comp,
           s.id as sid, s.name as sname, s.level as slevel, t.display_name as tname, mb.display_name as mname,
           (l.status = 'cancelled' and l.attendance is null) as closed,
           (l.attendance is null and l.status <> 'cancelled' and l.lesson_date <= today) as due
      from lessons l
      join students s on s.id = l.student_id and s.org_id = l.org_id
      left join memberships t  on t.id = l.taught_by and t.org_id = l.org_id
      left join memberships mb on mb.user_id = l.attendance_marked_by and mb.org_id = l.org_id
     where l.org_id = p_org and l.lesson_date between p_from and p_to and (p_tutor is null or l.taught_by = p_tutor)),
  d as (
    select base.*, case when closed then 'cancelled' when attendance is not null then 'marked' when lesson_date > today then 'future' else 'open' end as state
      from base),
  c as (select count(*)::int as n_all, (count(*) filter (where due))::int as n_unmarked, (count(*) filter (where attendance is not null))::int as n_marked,
                                  (count(*) filter (where trial))::int as n_trial from d),
  pg_rows as (
    select * from d
     where st = 'all' or (st = 'unmarked' and due) or (st = 'marked' and attendance is not null) or (st = 'trial' and trial)
     order by lesson_date, start_time, sname, id
     limit sz offset (pg - 1) * sz)
  select (select row_to_json(c) from c)::jsonb,
         coalesce((select jsonb_agg(jsonb_build_object(
           'lesson_id', id, 'lesson_date', lesson_date, 'start_time', start_time, 'end_time', end_time,
           'student_id', sid, 'student_name', sname, 'student_level', slevel, 'subject', subject,
           'tutor_id', taught_by, 'tutor_name', tname,
           'attendance', attendance, 'status', status, 'state', state, 'trial', trial, 'remarks', remarks,
           'marked_at', attendance_marked_at, 'marked_by_name', mname,
           'charge_pending', (attendance in ('absent', 'cancelled_early', 'late_cancelled') and no_comp),
           'session_id', session_id,
           'can_mark', (can_tt and state = 'open'), 'can_correct', (can_tt and state = 'marked'))
           order by lesson_date, start_time, sname, id) from pg_rows), '[]'::jsonb)
    into cnt, rows;

  total := case st when 'unmarked' then (cnt->>'n_unmarked')::int when 'marked' then (cnt->>'n_marked')::int when 'trial' then (cnt->>'n_trial')::int else (cnt->>'n_all')::int end;
  select coalesce(jsonb_agg(jsonb_build_object('id', m.id, 'name', m.display_name) order by m.display_name, m.id), '[]'::jsonb) into tutors
    from memberships m where m.org_id = p_org and m.role = 'tutor' and m.status in ('active', 'invited');

  return jsonb_build_object('today', today, 'can_mark', can_tt, 'page', pg, 'size', sz, 'total', total,
                            'counts', jsonb_build_object('all', (cnt->>'n_all')::int, 'unmarked', (cnt->>'n_unmarked')::int,
                                                         'marked', (cnt->>'n_marked')::int, 'trial', (cnt->>'n_trial')::int),
                            'tutors', tutors, 'rows', rows);
end $$;

-- ---------------------------------------------------------------- the toggle
create or replace function public.staff_set_trial(p_lesson uuid, p_trial boolean) returns jsonb
language plpgsql security definer set search_path = public as $$
declare l lessons;
begin
  if auth.uid() is null then raise exception 'NOT_FOUND' using errcode = 'P0001'; end if;
  select * into l from lessons where id = p_lesson;
  if not found then raise exception 'NOT_FOUND' using errcode = 'P0001'; end if;
  perform staff_attendance_gate(l.org_id, true);                         -- member of this centre as owner / staff, with manage_timetable
  if p_trial is null then raise exception 'BAD_VALUE: choose trial or not a trial' using errcode = 'P0001'; end if;
  if l.trial = p_trial then
    raise exception 'NO_CHANGE: the lesson is already %', case when p_trial then 'a trial lesson' else 'not a trial lesson' end using errcode = 'P0001'; end if;

  update lessons set trial = p_trial where id = l.id;
  insert into audit_log(org_id, actor, action, table_name, row_id, before, after)
  values (l.org_id, auth.uid(), 'staff_set_trial', 'lessons', l.id::text,
          jsonb_build_object('trial', l.trial), jsonb_build_object('trial', p_trial));
  return jsonb_build_object('lesson_id', l.id, 'trial', p_trial);
end $$;

revoke all on function public.staff_set_trial(uuid, boolean) from public, anon;
grant execute on function public.staff_set_trial(uuid, boolean) to authenticated;
revoke all on function public.staff_lessons(uuid, date, date, uuid, text, int, int) from public, anon;
grant execute on function public.staff_lessons(uuid, date, date, uuid, text, int, int) to authenticated;

-- #####################################################################################################
-- ### PART 6 of 21 — centre timetable + holiday band
-- ### source branch: claude/t3-6-timetable   file: db/migration_staff_timetable.sql   undo: db/migration_staff_timetable_down.sql
-- ### (if an error appears, search this file for the nearest "### PART" line above the error line: that is the part that failed)
-- #####################################################################################################
-- =====================================================================================================
-- T3 step 6 — the centre Timetable, READ ONLY: staff_timetable(...)                undo: migration_staff_timetable_down.sql
-- =====================================================================================================
-- Needs migration_staff_attendance.sql (it reuses staff_attendance_gate) and everything before it (lessons.taught_by, attendance, trial, holidays).
-- ADD-ONLY: one new function; no table, column, trigger or policy is touched. Nothing here writes. (Weekly slots, the generator and moving a
-- lesson are step 7+.)
--
-- WHAT IT IS: the lessons of a date range (at most 62 days; the page asks for one week), as a list the phone can show day by day, plus the
-- holidays that fall in the range. One call returns everything the screen draws.
--
-- WHO MAY CALL (decided in the T3 plan, section 1: "Timetable: view = any owner / staff")
--   an active OWNER or STAFF member of this centre, whatever their permissions. A tutor, a parent, switched-off staff, a stranger, a solo
--   organisation, an unknown id: the same NOT_FOUND, so ids can't be probed. A tutor never gets this (they have only tutor_my_lessons).
--
-- WHAT COMES BACK (explicit columns, never l.*): NO MONEY (no rate, amount, paid, compensation, *_cents; a lesson's price is not needed to read
--   a timetable) and no phone numbers or guardians. Per lesson: date, time, duration, student name and level, subject, tutor (name, or
--   'Former tutor' when the person has since been switched off, or null = NO TUTOR), trial, attendance state, cancelled, postponed, holiday
--   (name) and the class (session_id) it belongs to.
--   * no_tutor is true for a lesson with no tutor that is NOT cancelled: exactly the lessons staff_home counts as "no tutor, next 14 days",
--     so the Home tile and this list always agree.
--   * online_link: there is no such column yet (the lesson link arrives with T6 / step 7), so it is always null and the page says "Not set".
--   * Nothing needs a room or a branch: a remote 1-to-1 centre has neither, and every filter below is optional.
--
-- FILTERS (all optional, all checked to belong to THIS centre, else NOT_FOUND)
--   p_tutor     a memberships.id
--   p_student   a students.id
--   p_notutor   true = only lessons nobody teaches yet (what the Home tile links to)
--   p_branch    a branches.id. LESSONS DO NOT CARRY A BRANCH TODAY (no column on lessons, students or weekly slots), so this can't narrow the
--               lessons; it chooses which HOLIDAYS apply: the whole-centre ones plus that branch's. With no branch chosen every holiday shows
--               (a branch's own holiday is named after its branch) but only whole-centre holidays flag a lesson. Real branch filtering of
--               lessons arrives with rooms in step 7.
--   paging      p_page / p_size (1..100, default 50), server-side, so a 400-student centre never sends a month of lessons at once.
--
-- DAYS are the centre's own calendar days (organisations.timezone). Run on the DEV project first. Safe to run twice.
-- =====================================================================================================
create or replace function public.staff_timetable(p_org uuid, p_from date, p_to date, p_tutor uuid default null, p_branch uuid default null,
                                                  p_student uuid default null, p_page int default 1, p_notutor boolean default false,
                                                  p_size int default 50) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare today date := staff_attendance_gate(p_org, false);
        pg int := coalesce(p_page, 1); sz int := coalesce(p_size, 50); nt boolean := coalesce(p_notutor, false);
        cnt jsonb; rows jsonb; tutors jsonb; branches jsonb; studs jsonb; hols jsonb; total int; n_studs int;
begin
  if p_from is null or p_to is null or p_to < p_from or p_to - p_from > 62 then
    raise exception 'BAD_RANGE: ask for at most 62 days' using errcode = 'P0001'; end if;
  if pg < 1 or pg > 100000 then raise exception 'BAD_PAGE: no such page' using errcode = 'P0001'; end if;
  if sz < 1 or sz > 100 then raise exception 'BAD_PAGE: ask for 1 to 100 lessons at a time' using errcode = 'P0001'; end if;
  if p_tutor is not null and not exists (select 1 from memberships m where m.id = p_tutor and m.org_id = p_org) then
    raise exception 'NOT_FOUND' using errcode = 'P0001'; end if;
  if p_branch is not null and not exists (select 1 from branches b where b.id = p_branch and b.org_id = p_org) then
    raise exception 'NOT_FOUND' using errcode = 'P0001'; end if;
  if p_student is not null and not exists (select 1 from students s where s.id = p_student and s.org_id = p_org) then
    raise exception 'NOT_FOUND' using errcode = 'P0001'; end if;

  -- holidays touching the range (a branch's own holiday is labelled with the branch, so it can't be mistaken for the whole centre's)
  select coalesce(jsonb_agg(jsonb_build_object('id', h.id, 'name', h.name, 'starts_on', h.starts_on, 'ends_on', h.ends_on,
                                               'branch_id', h.branch_id, 'branch_name', b.name) order by h.starts_on, h.name, h.id), '[]'::jsonb)
    into hols
    from holidays h left join branches b on b.id = h.branch_id and b.org_id = h.org_id
   where h.org_id = p_org and h.starts_on <= p_to and h.ends_on >= p_from
     and (p_branch is null or h.branch_id is null or h.branch_id = p_branch);

  with base as (
    select l.id, l.lesson_date, l.start_time, l.end_time, l.subject, l.status, l.attendance, l.trial, l.postponed, l.session_id, l.taught_by,
           s.id as sid, s.name as sname, s.level as slevel, t.status as tstatus, t.display_name as tname,
           (l.status = 'cancelled' and l.attendance is null) as closed,
           (l.taught_by is null and l.status <> 'cancelled') as no_tutor,
           (select h.name from holidays h where h.org_id = p_org and l.lesson_date between h.starts_on and h.ends_on
               and (h.branch_id is null or h.branch_id = p_branch) order by h.starts_on, h.name limit 1) as holiday
      from lessons l
      join students s on s.id = l.student_id and s.org_id = l.org_id
      left join memberships t on t.id = l.taught_by and t.org_id = l.org_id
     where l.org_id = p_org and l.lesson_date between p_from and p_to
       and (p_tutor is null or l.taught_by = p_tutor) and (p_student is null or l.student_id = p_student)),
  d as (
    select base.*, case when closed then 'cancelled' when attendance is not null then 'marked' when lesson_date > today then 'future' else 'open' end as state
      from base),
  c as (select count(*)::int as n_all, (count(*) filter (where no_tutor))::int as n_notutor,
               (count(*) filter (where status = 'cancelled'))::int as n_cancelled, (count(*) filter (where holiday is not null))::int as n_holiday from d),
  pg_rows as (
    select * from d where (not nt or no_tutor)
     order by lesson_date, start_time, sname, id
     limit sz offset (pg - 1) * sz)
  select (select row_to_json(c) from c)::jsonb,
         coalesce((select jsonb_agg(jsonb_build_object(
           'lesson_id', id, 'lesson_date', lesson_date, 'start_time', start_time, 'end_time', end_time,
           'minutes', (extract(epoch from (end_time - start_time)) / 60)::int,
           'student_id', sid, 'student_name', sname, 'student_level', slevel, 'subject', subject,
           'tutor_id', taught_by,
           'tutor_name', case when taught_by is null then null when tstatus is null or tstatus = 'disabled' then 'Former tutor' else coalesce(tname, 'Tutor') end,
           'no_tutor', no_tutor, 'trial', trial, 'attendance', attendance, 'state', state,
           'cancelled', (status = 'cancelled'), 'postponed', postponed, 'holiday', holiday, 'session_id', session_id,
           'online_link', null)
           order by lesson_date, start_time, sname, id) from pg_rows), '[]'::jsonb)
    into cnt, rows;
  total := case when nt then (cnt->>'n_notutor')::int else (cnt->>'n_all')::int end;

  select coalesce(jsonb_agg(jsonb_build_object('id', m.id, 'name', m.display_name) order by m.display_name, m.id), '[]'::jsonb) into tutors
    from memberships m where m.org_id = p_org and m.role = 'tutor' and m.status in ('active', 'invited');
  select coalesce(jsonb_agg(jsonb_build_object('id', b.id, 'name', b.name) order by b.name, b.id), '[]'::jsonb) into branches
    from branches b where b.org_id = p_org;
  -- who has a lesson in this range (for the student filter): at most 300 names, and the page says so when there are more
  select count(distinct l.student_id) into n_studs from lessons l where l.org_id = p_org and l.lesson_date between p_from and p_to;
  select coalesce(jsonb_agg(jsonb_build_object('id', x.id, 'name', x.name) order by x.name, x.id), '[]'::jsonb) into studs
    from (select s.id, s.name from students s
           where s.org_id = p_org and exists (select 1 from lessons l where l.org_id = p_org and l.student_id = s.id and l.lesson_date between p_from and p_to)
           order by s.name, s.id limit 300) x;

  return jsonb_build_object('today', today, 'page', pg, 'size', sz, 'total', total, 'counts', cnt, 'holidays', hols,
                            'tutors', tutors, 'branches', branches, 'students', studs, 'students_more', n_studs > 300, 'rows', rows);
end $$;

revoke all on function public.staff_timetable(uuid, date, date, uuid, uuid, uuid, int, boolean, int) from public, anon;
grant execute on function public.staff_timetable(uuid, date, date, uuid, uuid, uuid, int, boolean, int) to authenticated;

-- #####################################################################################################
-- ### PART 7 of 21 — weekly slots with tutors, lesson generator
-- ### source branch: claude/t3-7-slots   file: db/migration_staff_slots.sql   undo: db/migration_staff_slots_down.sql
-- ### (if an error appears, search this file for the nearest "### PART" line above the error line: that is the part that failed)
-- #####################################################################################################
-- =====================================================================================================
-- T3 step 7 — centre weekly slots with tutors, the lesson generator, and who teaches whom          undo: migration_staff_slots_down.sql
-- =====================================================================================================
-- Needs migration_staff_timetable.sql (and everything before it: lessons.taught_by / session_id, attendance, org settings, holidays).
--
-- WHAT IT ADDS
--   recurring_slots.taught_by    the tutor (memberships.id) who teaches the weekly slot; null = no tutor yet (flagged amber on the Timetable)
--   recurring_slots.session_key  slots of one GROUP class share a key (one row per student, like lessons share a session_id)
--   students.online_link         optional https:// lesson link, per student (centre students only; see staff_set_student_link)
--   student_tutors               the students each tutor is ASSIGNED to; staff keep it, tutors never read or write it (T6 reads it)
--   staff_slots                  read   the weekly slots (rate only for people who may edit)
--   staff_pick_students          read   a name search for the slot form (names and levels only)
--   staff_save_slot              write  add / change a weekly slot (one student, or several = a group class)
--   staff_stop_slot              write  stop a weekly slot (it is switched off, never deleted: history stays)
--   staff_generate_lessons       write  create the lessons of the next N weeks from the active slots; safe to press twice
--   staff_student_tutors         read   a student's assigned tutors + history + online link (for the student sheet)
--   staff_set_student_tutors     write  set the students' assigned tutors
--   staff_set_student_link       write  set / clear a student's online link
--   tutor_lesson_links           read   a tutor's own lessons' online links (the tutor's other function is unchanged: it never has to change)
--   staff_timetable              replaced (same arguments): its 'online_link' is now the student's link instead of always null
--
-- WHO MAY CALL (same words as the rest of the staff screens)
--   reading   an active OWNER or STAFF member of this CENTRE, whatever their permissions
--   writing   the same, with manage_timetable (owners always). The link may also be set by manage_students.
--   a tutor / a parent / switched-off staff / a stranger / a solo organisation / an unknown id  →  NOT_FOUND (same words, so ids can't be probed)
--   staff of this centre without the permission                                                 →  NOT_ALLOWED
-- Tutors still have NO table access: they read neither slots nor student_tutors, and never see a rate. A slot's rate is the lesson's price
-- (staff only); tutor_my_lessons and tutor_lesson_links never return money.
--
-- THE GENERATOR (staff_generate_lessons) in plain words
--   * For every ACTIVE weekly slot and every day in the range that falls on the slot's weekday it makes one lesson per student (a group class
--     gets one lesson row per student, tied by the same session_id), with the slot's tutor, time, subject and rate. Lessons start as
--     'scheduled'; for a centre the status follows attendance, set when someone marks it.
--   * IDEMPOTENT: a lesson is keyed on slot + date (lessons.slot_id + slot_date, exactly the key the solo pages use), and a hand-made lesson for
--     the same student, day and start time counts too. Pressing it twice, or two people pressing it together, creates nothing twice (the call
--     takes a per-centre lock). A lesson that was moved keeps its slot_date, so the original day is not made again.
--   * SKIPS a day covered by a whole-centre holiday when the centre's setting calendar.skip_holidays is on (default on). Branch holidays do not
--     skip anything: slots and students carry no branch. SKIPS a student whose lessons have ended (students.end_date, inclusive).
--   * Never makes a lesson in the past (the range starts today at the earliest), and at most 62 days at a time. Default: today + 4 weeks.
--   * Nothing needs a room, a class or a branch: a remote 1-to-1 centre has none.
--
-- DATA-MODEL CHOICES (plain words)
--   * recurring_slots.tutor_id and lessons.tutor_id are NOT NULL logins; as in staff_save_student a centre's rows are filed under the centre
--     OWNER's login, so removing a staff login can't make the centre's timetable disappear. The person who TEACHES is taught_by.
--   * A stopped slot is active = false (like solo tutors' Planner). Lessons it already made are left alone (real data); the answer says how many.
--   * student_tutors is append-only history: removing a tutor from a student ends that row (active = false, until = today) and never deletes it;
--     adding them again later starts a new row. Only the functions write it (there is no write policy), and the audit log records every change.
--   * "A tutor and a student must belong to the same centre" is a trigger (org_tutor_same_org_guard, the same pattern as org_same_org_guard)
--     on student_tutors and on recurring_slots.taught_by, on top of the composite foreign keys.
-- Run on the DEV project first. Safe to run twice.
-- =====================================================================================================

-- ---------------------------------------------------------------- columns
alter table public.recurring_slots add column if not exists taught_by uuid;                 -- memberships.id of the tutor
alter table public.recurring_slots add column if not exists session_key uuid;               -- slots of one group class share a key
alter table public.students        add column if not exists online_link text;               -- optional https:// lesson link
do $$ begin
  if not exists (select 1 from pg_constraint where conname = 'slots_taught_by_same_org') then
    -- same organisation only; if the person is removed the slot keeps its organisation (set null on taught_by ONLY)
    alter table public.recurring_slots add constraint slots_taught_by_same_org
      foreign key (taught_by, org_id) references public.memberships(id, org_id) on delete set null (taught_by);
  end if;
  if not exists (select 1 from pg_constraint where conname = 'students_online_link_ok') then
    alter table public.students add constraint students_online_link_ok
      check (online_link is null or (online_link ~ '^https://[^[:space:]]+$' and length(online_link) <= 500));
  end if;
end $$;
create index if not exists slots_taught_by on public.recurring_slots(taught_by) where taught_by is not null;
create index if not exists slots_session_key on public.recurring_slots(session_key) where session_key is not null;

-- ---------------------------------------------------------------- who teaches whom (assigned students): staff keep it, tutors never touch it
create table if not exists public.student_tutors (
  id            uuid primary key default gen_random_uuid(),
  org_id        uuid not null references public.organisations(id) on delete cascade,
  student_id    uuid not null,
  membership_id uuid not null,                                   -- the tutor (memberships.id)
  since         date not null default current_date,
  until         date,                                            -- set when the assignment ends (the row is kept as history)
  active        boolean not null default true,
  created_by    uuid,
  created_at    timestamptz not null default now(),
  check (active or until is not null),
  foreign key (student_id, org_id)    references public.students(id, org_id)    on delete cascade,
  foreign key (membership_id, org_id) references public.memberships(id, org_id) on delete cascade
);
create unique index if not exists student_tutors_one_active on public.student_tutors(student_id, membership_id) where active;
create index if not exists student_tutors_org_student on public.student_tutors(org_id, student_id);
create index if not exists student_tutors_tutor on public.student_tutors(membership_id) where active;

-- a tutor and a student (or a slot's tutor and its student) must belong to the same centre: a plain message, on top of the composite keys
create or replace function public.org_tutor_same_org_guard() returns trigger
language plpgsql security definer set search_path = public as $$
declare n jsonb := to_jsonb(new); o jsonb := case when tg_op = 'UPDATE' then to_jsonb(old) end;
        mem uuid := coalesce(nullif(n->>'membership_id', ''), nullif(n->>'taught_by', ''))::uuid;
        omem text := case when o is null then null else coalesce(nullif(o->>'membership_id', ''), nullif(o->>'taught_by', '')) end;
        stu uuid := nullif(n->>'student_id', '')::uuid;
begin
  if mem is not null and (o is null or mem::text is distinct from omem or n->>'org_id' is distinct from o->>'org_id') then
    if not exists (select 1 from memberships m where m.id = mem and m.org_id = new.org_id and m.status <> 'disabled') then
      raise exception 'A tutor and a student must belong to the same centre (that person isn''t an active member here)' using errcode = '42501';
    end if;
  end if;
  if tg_table_name = 'student_tutors' and stu is not null and (o is null or n->>'student_id' is distinct from o->>'student_id' or n->>'org_id' is distinct from o->>'org_id') then
    if not exists (select 1 from students s join organisations g on g.id = s.org_id and g.kind = 'centre' where s.id = stu and s.org_id = new.org_id) then
      raise exception 'A tutor and a student must belong to the same centre (that student isn''t one of this centre''s)' using errcode = '42501';
    end if;
  end if;
  return new;
end $$;
drop trigger if exists org_tutor_same_org_guard on public.student_tutors;
create trigger org_tutor_same_org_guard before insert or update on public.student_tutors for each row execute function public.org_tutor_same_org_guard();
drop trigger if exists org_tutor_same_org_guard on public.recurring_slots;
create trigger org_tutor_same_org_guard before insert or update on public.recurring_slots for each row execute function public.org_tutor_same_org_guard();
revoke all on function public.org_tutor_same_org_guard() from public, anon, authenticated;

alter table public.student_tutors enable row level security;
drop policy if exists org_read on public.student_tutors;
create policy org_read on public.student_tutors for select using (org_can_read(org_id));           -- owners and staff read; there is NO write policy (functions only)
drop trigger if exists audit_row on public.student_tutors;
create trigger audit_row after insert or update or delete on public.student_tutors for each row execute function public.audit_row();
revoke all on public.student_tutors from anon, authenticated;
grant select on public.student_tutors to authenticated;

-- ---------------------------------------------------------------- the gate every function starts with (internal; not callable from the browser)
-- p_write false: any active owner / staff member.  true: also needs manage_timetable.  Returns the centre's own today.
create or replace function public.staff_slots_gate(p_org uuid, p_write boolean) returns date
language plpgsql stable security definer set search_path = public as $$
declare tz text;
begin
  if auth.uid() is null then raise exception 'NOT_FOUND' using errcode = 'P0001'; end if;
  select o.timezone into tz from organisations o where o.id = p_org and o.kind = 'centre';
  if tz is null or not exists (select 1 from memberships m where m.org_id = p_org and m.user_id = auth.uid() and m.status = 'active'
                               and m.role in ('owner', 'staff')) then
    raise exception 'NOT_FOUND' using errcode = 'P0001';
  end if;
  if p_write and not org_can(p_org, 'manage_timetable') then
    raise exception 'NOT_ALLOWED: your account can''t change the timetable at this centre' using errcode = '42501';
  end if;
  return (now() at time zone tz)::date;
end $$;
revoke all on function public.staff_slots_gate(uuid, boolean) from public, anon, authenticated;

-- ---------------------------------------------------------------- 1. the weekly slots (read)
-- A row is one slot, or one GROUP class (the slots sharing a session_key, with all its students). Only ACTIVE slots. weekday 0 = Monday … 6 = Sunday,
-- like the Planner. `rate` (S$ per hour) comes back ONLY to someone who may edit the timetable; everyone else gets null. p_q searches student names
-- and subjects. generated_until = the last day a slot has already made a lesson for (null = none yet).
create or replace function public.staff_slots(p_org uuid, p_tutor uuid default null, p_q text default null, p_page int default 1, p_size int default 25)
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare today date := staff_slots_gate(p_org, false); can_edit boolean := org_can(p_org, 'manage_timetable');
        q text := nullif(trim(coalesce(p_q, '')), ''); pat text; pg int := coalesce(p_page, 1); sz int := coalesce(p_size, 25);
        rows jsonb; tutors jsonb; total int; gen date;
begin
  if q is not null and length(q) > 100 then raise exception 'BAD_SEARCH: search for at most 100 characters' using errcode = 'P0001'; end if;
  if pg < 1 or pg > 100000 then raise exception 'BAD_PAGE: no such page' using errcode = 'P0001'; end if;
  if sz < 1 or sz > 100 then raise exception 'BAD_PAGE: ask for 1 to 100 slots at a time' using errcode = 'P0001'; end if;
  if p_tutor is not null and not exists (select 1 from memberships m where m.id = p_tutor and m.org_id = p_org) then
    raise exception 'NOT_FOUND' using errcode = 'P0001'; end if;
  if q is not null then pat := '%' || replace(replace(replace(q, '\', '\\'), '%', '\%'), '_', '\_') || '%'; end if;

  with g as (
    select coalesce(sl.session_key, sl.id) as gk, min(sl.id::text)::uuid as first_id, count(*)::int as n,
           min(sl.weekday) as weekday, min(sl.start_time) as start_time, min(sl.end_time) as end_time, min(sl.subject) as subject, min(sl.rate) as rate,
           (array_agg(sl.taught_by))[1] as taught_by, bool_or(sl.session_key is not null) as is_group,
           jsonb_agg(jsonb_build_object('id', s.id, 'name', s.name, 'level', s.level,
                       'ended', (s.end_date is not null and s.end_date < today), 'slot_id', sl.id) order by s.name, s.id) as studs
      from recurring_slots sl join students s on s.id = sl.student_id and s.org_id = sl.org_id
     where sl.org_id = p_org and sl.active and (p_tutor is null or sl.taught_by = p_tutor)
       and (q is null or sl.subject ilike pat or s.name ilike pat)
     group by coalesce(sl.session_key, sl.id)),
  paged as (select * from g order by weekday, start_time, (studs->0->>'name'), gk limit sz offset (pg - 1) * sz)
  select (select count(*) from g)::int,
         coalesce((select jsonb_agg(jsonb_build_object(
           'key', p.gk, 'slot_id', p.first_id, 'weekday', p.weekday, 'start_time', p.start_time, 'end_time', p.end_time,
           'minutes', (extract(epoch from (p.end_time - p.start_time)) / 60)::int, 'subject', p.subject,
           'rate', case when can_edit then p.rate end,
           'tutor_id', p.taught_by,
           'tutor_name', case when p.taught_by is null then null when t.status is null or t.status = 'disabled' then 'Former tutor' else coalesce(t.display_name, 'Tutor') end,
           'no_tutor', (p.taught_by is null or t.status is null or t.status = 'disabled'),
           'is_group', p.is_group, 'students', p.studs)
           order by p.weekday, p.start_time, (p.studs->0->>'name'), p.gk)
           from paged p left join memberships t on t.id = p.taught_by and t.org_id = p_org), '[]'::jsonb)
    into total, rows;
  select coalesce(jsonb_agg(jsonb_build_object('id', m.id, 'name', m.display_name) order by m.display_name, m.id), '[]'::jsonb) into tutors
    from memberships m where m.org_id = p_org and m.role = 'tutor' and m.status in ('active', 'invited');
  select max(l.lesson_date) into gen from lessons l where l.org_id = p_org and l.slot_id is not null;
  return jsonb_build_object('today', today, 'can_edit', can_edit, 'page', pg, 'size', sz, 'total', total, 'generated_until', gen,
                            'tutors', tutors, 'rows', rows);
end $$;
revoke all on function public.staff_slots(uuid, uuid, text, int, int) from public, anon;
grant execute on function public.staff_slots(uuid, uuid, text, int, int) to authenticated;

-- ---------------------------------------------------------------- 2. find students for the slot form (names and levels only; active, lessons not ended)
create or replace function public.staff_pick_students(p_org uuid, p_q text default null, p_limit int default 20)
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare today date := staff_slots_gate(p_org, true); q text := nullif(trim(coalesce(p_q, '')), ''); pat text; lim int := least(greatest(coalesce(p_limit, 20), 1), 50);
begin
  if q is not null and length(q) > 100 then raise exception 'BAD_SEARCH: search for at most 100 characters' using errcode = 'P0001'; end if;
  if q is not null then pat := '%' || replace(replace(replace(q, '\', '\\'), '%', '\%'), '_', '\_') || '%'; end if;
  return coalesce((select jsonb_agg(jsonb_build_object('id', x.id, 'name', x.name, 'level', x.level) order by lower(x.name), x.id)
                     from (select s.id, s.name, s.level from students s
                            where s.org_id = p_org and (s.end_date is null or s.end_date >= today) and (q is null or s.name ilike pat)
                            order by lower(s.name), s.id limit lim) x), '[]'::jsonb);
end $$;
revoke all on function public.staff_pick_students(uuid, text, int) from public, anon;
grant execute on function public.staff_pick_students(uuid, text, int) to authenticated;

-- ---------------------------------------------------------------- 3. add / change a weekly slot
-- p_slot null = ADD one slot per student in p_students (1 to 30; two or more = a group class, tied by a session_key).
-- p_slot set = CHANGE that slot (and the rest of its group): weekday, time, tutor (null = no tutor yet), subject, rate (null = keep). The students
--   of a slot can't be changed (stop it and add a new one), so p_students must be null.
-- Checks: weekday 0-6; start before end, 15 minutes to 8 hours, same day; rate 0 to 1000 per hour (needed when adding); tutor an active or invited
--   member of this centre; every student in this centre and not ended; a student can't have two weekly slots that overlap.
-- Lessons ALREADY made from the slot are not rewritten (real data, maybe already marked); the answer says how many upcoming ones are left.
create or replace function public.staff_save_slot(p_org uuid, p_slot uuid, p_students uuid[], p_weekday int, p_start time, p_end time,
                                                  p_tutor uuid default null, p_subject text default null, p_rate numeric default null)
returns jsonb language plpgsql security definer set search_path = public as $$
declare today date := staff_slots_gate(p_org, true); subj text := nullif(trim(coalesce(p_subject, '')), ''); mins int;
        sids uuid[]; sid uuid; sl recurring_slots; key uuid; owner_uid uuid; ids uuid[] := '{}'; sr students; clash text; new_id uuid; made int; r numeric(8,2);
begin
  if p_weekday is null or p_weekday < 0 or p_weekday > 6 then raise exception 'BAD_SLOT: pick a day of the week' using errcode = 'P0001'; end if;
  if p_start is null or p_end is null then raise exception 'BAD_TIME: give a start and an end time' using errcode = 'P0001'; end if;
  mins := (extract(epoch from (p_end - p_start)) / 60)::int;
  if mins <= 0 then raise exception 'BAD_TIME: the lesson must end after it starts' using errcode = 'P0001'; end if;
  if mins < 15 or mins > 480 then raise exception 'BAD_TIME: a lesson lasts 15 minutes to 8 hours' using errcode = 'P0001'; end if;
  if subj is not null and length(subj) > 60 then raise exception 'BAD_SLOT: the subject is too long (60 characters at most)' using errcode = 'P0001'; end if;
  if p_rate is not null and (p_rate < 0 or p_rate > 1000) then raise exception 'BAD_RATE: the rate per hour must be between 0 and 1000' using errcode = 'P0001'; end if;
  r := round(p_rate, 2);
  if p_tutor is not null and not exists (select 1 from memberships m where m.id = p_tutor and m.org_id = p_org and m.role in ('tutor', 'staff', 'owner') and m.status in ('active', 'invited')) then
    raise exception 'NOT_AVAILABLE: that person can''t be given lessons at this centre' using errcode = 'P0001'; end if;

  if p_slot is null then
    if p_rate is null then raise exception 'BAD_RATE: type the rate per hour' using errcode = 'P0001'; end if;
    select coalesce(array_agg(distinct x), '{}') into sids from unnest(coalesce(p_students, '{}')) x where x is not null;
    if coalesce(array_length(sids, 1), 0) < 1 then raise exception 'BAD_STUDENTS: pick at least one student' using errcode = 'P0001'; end if;
    if array_length(sids, 1) > 30 then raise exception 'BAD_STUDENTS: a class has at most 30 students' using errcode = 'P0001'; end if;
    select m.user_id into owner_uid from memberships m where m.org_id = p_org and m.role = 'owner' and m.status = 'active' and m.user_id is not null order by m.created_at limit 1;
    if owner_uid is null then raise exception 'NOT_FOUND' using errcode = 'P0001'; end if;
    key := case when array_length(sids, 1) > 1 then gen_random_uuid() end;
    foreach sid in array sids loop
      select * into sr from students where id = sid and org_id = p_org;
      if not found then raise exception 'NOT_FOUND' using errcode = 'P0001'; end if;
      if sr.end_date is not null and sr.end_date < today then raise exception 'STUDENT_ENDED: %''s lessons have ended', sr.name using errcode = 'P0001'; end if;
      select s2.name into clash from recurring_slots x join students s2 on s2.id = x.student_id
       where x.org_id = p_org and x.active and x.student_id = sid and x.weekday = p_weekday and x.start_time < p_end and x.end_time > p_start limit 1;
      if found then raise exception 'SLOT_CLASH: % already has a weekly lesson at that time', clash using errcode = 'P0001'; end if;
    end loop;
    foreach sid in array sids loop
      insert into recurring_slots(tutor_id, org_id, student_id, weekday, start_time, end_time, subject, rate, level, split, taught_by, session_key)
      select owner_uid, p_org, s.id, p_weekday, p_start, p_end, subj, r, s.level, 1, p_tutor, key from students s where s.id = sid and s.org_id = p_org
      returning id into new_id;
      ids := ids || new_id;
    end loop;
    insert into audit_log(org_id, actor, action, table_name, row_id, after)
    values (p_org, auth.uid(), 'staff_save_slot', 'recurring_slots', ids[1]::text,
            jsonb_build_object('added', true, 'slot_ids', ids, 'weekday', p_weekday, 'start', p_start, 'end', p_end, 'tutor', p_tutor, 'students', sids));
    return jsonb_build_object('slot_ids', ids, 'added', array_length(ids, 1), 'lessons_left', 0);
  end if;

  -- change
  if p_students is not null then raise exception 'BAD_STUDENTS: to change who is in a slot, stop it and add a new one' using errcode = 'P0001'; end if;
  select * into sl from recurring_slots where id = p_slot and org_id = p_org and active;
  if not found then raise exception 'NOT_FOUND' using errcode = 'P0001'; end if;
  select coalesce(array_agg(x.id), '{}') into ids from recurring_slots x
   where x.org_id = p_org and x.active and (x.id = sl.id or (sl.session_key is not null and x.session_key = sl.session_key));
  for sid in select x.student_id from recurring_slots x where x.id = any(ids) loop
    select s2.name into clash from recurring_slots x join students s2 on s2.id = x.student_id
     where x.org_id = p_org and x.active and x.student_id = sid and not (x.id = any(ids)) and x.weekday = p_weekday and x.start_time < p_end and x.end_time > p_start limit 1;
    if found then raise exception 'SLOT_CLASH: % already has a weekly lesson at that time', clash using errcode = 'P0001'; end if;
  end loop;
  update recurring_slots set weekday = p_weekday, start_time = p_start, end_time = p_end, subject = subj, rate = coalesce(r, rate), taught_by = p_tutor
   where id = any(ids);
  select count(*) into made from lessons l where l.org_id = p_org and l.slot_id = any(ids) and l.lesson_date >= today and l.attendance is null and l.status <> 'cancelled';
  insert into audit_log(org_id, actor, action, table_name, row_id, before, after)
  values (p_org, auth.uid(), 'staff_save_slot', 'recurring_slots', sl.id::text,
          jsonb_build_object('weekday', sl.weekday, 'start', sl.start_time, 'end', sl.end_time, 'tutor', sl.taught_by),
          jsonb_build_object('slot_ids', ids, 'weekday', p_weekday, 'start', p_start, 'end', p_end, 'tutor', p_tutor, 'rate_changed', p_rate is not null));
  return jsonb_build_object('slot_ids', ids, 'added', 0, 'lessons_left', made);
end $$;
revoke all on function public.staff_save_slot(uuid, uuid, uuid[], int, time, time, uuid, text, numeric) from public, anon;
grant execute on function public.staff_save_slot(uuid, uuid, uuid[], int, time, time, uuid, text, numeric) to authenticated;

-- ---------------------------------------------------------------- 4. stop a weekly slot (the whole group class if it is one)
create or replace function public.staff_stop_slot(p_org uuid, p_slot uuid) returns jsonb
language plpgsql security definer set search_path = public as $$
declare today date := staff_slots_gate(p_org, true); sl recurring_slots; ids uuid[]; made int;
begin
  select * into sl from recurring_slots where id = p_slot and org_id = p_org;
  if not found then raise exception 'NOT_FOUND' using errcode = 'P0001'; end if;
  select coalesce(array_agg(x.id), '{}') into ids from recurring_slots x
   where x.org_id = p_org and x.active and (x.id = sl.id or (sl.session_key is not null and x.session_key = sl.session_key));
  update recurring_slots set active = false where id = any(ids);
  select count(*) into made from lessons l where l.org_id = p_org and l.slot_id = any(ids) and l.lesson_date >= today and l.attendance is null and l.status <> 'cancelled';
  if coalesce(array_length(ids, 1), 0) > 0 then
    insert into audit_log(org_id, actor, action, table_name, row_id, after)
    values (p_org, auth.uid(), 'staff_stop_slot', 'recurring_slots', sl.id::text, jsonb_build_object('slot_ids', ids, 'lessons_left', made));
  end if;
  return jsonb_build_object('stopped', coalesce(array_length(ids, 1), 0), 'lessons_left', made);
end $$;
revoke all on function public.staff_stop_slot(uuid, uuid) from public, anon;
grant execute on function public.staff_stop_slot(uuid, uuid) to authenticated;

-- ---------------------------------------------------------------- 5. create the lessons of the next weeks from the active slots
-- p_from default = the centre's today (never earlier); p_to default = p_from + 27 days (4 weeks); at most 62 days.
-- Answer: created (new lessons), skipped (already there: same slot and day, or a lesson for that student, day and start time), holidays (days
-- skipped because of a whole-centre holiday, when calendar.skip_holidays is on), ended (students whose lessons had ended), no_tutor (new lessons
-- made with no tutor: the slot has none, or its tutor has since been switched off), on_holiday (new lessons that fall on a holiday because the
-- centre switched skipping off), slots (active slots looked at). The settings are read as of TODAY (a process rule).
create or replace function public.staff_generate_lessons(p_org uuid, p_from date default null, p_to date default null) returns jsonb
language plpgsql security definer set search_path = public as $$
declare today date := staff_slots_gate(p_org, true); f date := coalesce(p_from, today); t date; skip boolean; res jsonb;
begin
  t := coalesce(p_to, f + 27);
  if f < today then raise exception 'BAD_RANGE: lessons can''t be created for days that have passed' using errcode = 'P0001'; end if;
  if t < f or t - f > 62 then raise exception 'BAD_RANGE: create at most 62 days at a time' using errcode = 'P0001'; end if;
  skip := case when jsonb_typeof(org_settings_on(p_org, today) #> '{calendar,skip_holidays}') = 'boolean'
                then (org_settings_on(p_org, today) #>> '{calendar,skip_holidays}')::boolean else true end;      -- missing = on (the default)
  perform pg_advisory_xact_lock(hashtextextended('staff_generate_lessons:' || p_org::text, 0));        -- two people pressing together: one waits, then finds nothing to add

  with days as (select d::date as d from generate_series(f, t, interval '1 day') d),
  cand as (
    select sl.id as slot_id, sl.session_key, sl.tutor_id, sl.student_id, sl.start_time, sl.end_time, sl.subject, sl.level, sl.rate, sl.split,
           days.d, st.end_date,
           (select m.id from memberships m where m.id = sl.taught_by and m.org_id = p_org and m.status <> 'disabled') as ok_tutor,
           exists (select 1 from holidays h where h.org_id = p_org and h.branch_id is null and days.d between h.starts_on and h.ends_on) as is_hol,
           exists (select 1 from lessons l where l.org_id = p_org
                    and ((l.slot_id = sl.id and l.slot_date = days.d)
                      or (l.student_id = sl.student_id and l.lesson_date = days.d and l.start_time = sl.start_time))) as there
      from recurring_slots sl
      join students st on st.id = sl.student_id and st.org_id = sl.org_id
      join days on (extract(isodow from days.d)::int - 1) = sl.weekday
     where sl.org_id = p_org and sl.active),
  cls as (
    select cand.*, case when end_date is not null and d > end_date then 'ended'
                        when there then 'there'
                        when is_hol and skip then 'holiday'
                        else 'new' end as kind
      from cand),
  ins as (
    insert into lessons(tutor_id, org_id, student_id, slot_id, lesson_date, slot_date, start_time, end_time, subject, level, rate, split, amount,
                        status, paid, one_off, taught_by, session_id)
    select tutor_id, p_org, student_id, slot_id, d, d, start_time, end_time, subject, level, rate, coalesce(split, 1),
           round(round(rate * (extract(epoch from (end_time - start_time)) / 3600)::numeric, 2) / greatest(coalesce(split, 1), 1), 2),
           'scheduled', false, false, ok_tutor,
           case when session_key is null then null else md5(session_key::text || d::text)::uuid end     -- the same for every student of the class on that day
      from cls where kind = 'new'
    returning id)
  select jsonb_build_object(
           'from', f, 'to', t,
           'created', (select count(*) from ins),
           'skipped', count(*) filter (where kind = 'there'),
           'holidays', count(distinct d) filter (where kind = 'holiday'),
           'ended', count(*) filter (where kind = 'ended'),
           'no_tutor', count(*) filter (where kind = 'new' and ok_tutor is null),
           'on_holiday', count(*) filter (where kind = 'new' and is_hol),
           'slots', (select count(*) from recurring_slots x where x.org_id = p_org and x.active))
    into res from cls;
  insert into audit_log(org_id, actor, action, table_name, row_id, after) values (p_org, auth.uid(), 'staff_generate_lessons', 'lessons', null, res);
  return res;
end $$;
revoke all on function public.staff_generate_lessons(uuid, date, date) from public, anon;
grant execute on function public.staff_generate_lessons(uuid, date, date) to authenticated;

-- ---------------------------------------------------------------- 6. a student's assigned tutors, history and online link (for the student sheet)
-- can_edit = may change the assigned tutors (manage_timetable); can_link = may change the link (manage_timetable or manage_students).
create or replace function public.staff_student_tutors(p_org uuid, p_student uuid) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare today date := staff_slots_gate(p_org, false); s students; assigned jsonb; hist jsonb; opts jsonb;
begin
  select * into s from students where id = p_student and org_id = p_org;
  if not found then raise exception 'NOT_FOUND' using errcode = 'P0001'; end if;
  select coalesce(jsonb_agg(jsonb_build_object('id', m.id, 'name', coalesce(m.display_name, 'Tutor'), 'since', x.since) order by m.display_name, m.id), '[]'::jsonb) into assigned
    from student_tutors x join memberships m on m.id = x.membership_id and m.org_id = x.org_id
   where x.org_id = p_org and x.student_id = p_student and x.active;
  select coalesce(jsonb_agg(jsonb_build_object('name', coalesce(m.display_name, 'Tutor'), 'since', y.since, 'until', y.until) order by y.until desc, y.since desc), '[]'::jsonb) into hist
    from (select * from student_tutors z where z.org_id = p_org and z.student_id = p_student and not z.active order by z.until desc, z.since desc limit 10) y
    join memberships m on m.id = y.membership_id and m.org_id = y.org_id;
  select coalesce(jsonb_agg(jsonb_build_object('id', m.id, 'name', coalesce(m.display_name, 'Tutor')) order by m.display_name, m.id), '[]'::jsonb) into opts
    from memberships m where m.org_id = p_org and m.role = 'tutor' and m.status in ('active', 'invited');
  return jsonb_build_object('student_id', s.id, 'student_name', s.name, 'can_edit', org_can(p_org, 'manage_timetable'),
                            'can_link', org_can(p_org, 'manage_timetable') or org_can(p_org, 'manage_students'),
                            'online_link', s.online_link, 'assigned', assigned, 'history', hist, 'options', opts);
end $$;
revoke all on function public.staff_student_tutors(uuid, uuid) from public, anon;
grant execute on function public.staff_student_tutors(uuid, uuid) to authenticated;

-- ---------------------------------------------------------------- 7. set a student's assigned tutors
-- p_tutors = the full list wanted now (up to 20; empty = none). Tutors no longer on the list get their row ENDED (active false, until today),
-- new ones get a new row (since today). Nothing is deleted. Who is assigned decides which students a tutor may schedule for themselves (T6).
create or replace function public.staff_set_student_tutors(p_org uuid, p_student uuid, p_tutors uuid[]) returns jsonb
language plpgsql security definer set search_path = public as $$
declare today date := staff_slots_gate(p_org, true); want uuid[]; mid uuid; added int := 0; removed int := 0; n int;
begin
  if not exists (select 1 from students s where s.id = p_student and s.org_id = p_org) then raise exception 'NOT_FOUND' using errcode = 'P0001'; end if;
  select coalesce(array_agg(distinct x), '{}') into want from unnest(coalesce(p_tutors, '{}')) x where x is not null;
  if coalesce(array_length(want, 1), 0) > 20 then raise exception 'BAD_TUTORS: a student has at most 20 assigned tutors' using errcode = 'P0001'; end if;
  foreach mid in array want loop
    if not exists (select 1 from memberships m where m.id = mid and m.org_id = p_org and m.status in ('active', 'invited')) then
      raise exception 'NOT_AVAILABLE: that person can''t be given students at this centre' using errcode = 'P0001'; end if;
  end loop;
  update student_tutors set active = false, until = today
   where org_id = p_org and student_id = p_student and active and not (membership_id = any(want));
  get diagnostics removed = row_count;
  foreach mid in array want loop
    if not exists (select 1 from student_tutors x where x.org_id = p_org and x.student_id = p_student and x.membership_id = mid and x.active) then
      insert into student_tutors(org_id, student_id, membership_id, since, created_by) values (p_org, p_student, mid, today, auth.uid());
      added := added + 1;
    end if;
  end loop;
  select count(*) into n from student_tutors where org_id = p_org and student_id = p_student and active;
  if added + removed > 0 then
    insert into audit_log(org_id, actor, action, table_name, row_id, after)
    values (p_org, auth.uid(), 'staff_set_student_tutors', 'student_tutors', p_student::text, jsonb_build_object('added', added, 'removed', removed, 'tutors', want));
  end if;
  return jsonb_build_object('added', added, 'removed', removed, 'assigned', n);
end $$;
revoke all on function public.staff_set_student_tutors(uuid, uuid, uuid[]) from public, anon;
grant execute on function public.staff_set_student_tutors(uuid, uuid, uuid[]) to authenticated;

-- ---------------------------------------------------------------- 8. set or clear a student's online lesson link
-- https:// only, no spaces, 500 characters at most ('javascript:' and friends are refused). '' or null clears it. Not money.
create or replace function public.staff_set_student_link(p_org uuid, p_student uuid, p_link text) returns jsonb
language plpgsql security definer set search_path = public as $$
declare today date := staff_slots_gate(p_org, false); lk text := nullif(trim(coalesce(p_link, '')), ''); old text;
begin
  if not (org_can(p_org, 'manage_timetable') or org_can(p_org, 'manage_students')) then
    raise exception 'NOT_ALLOWED: your account can''t change students or the timetable at this centre' using errcode = '42501'; end if;
  select s.online_link into old from students s where s.id = p_student and s.org_id = p_org;
  if not found then raise exception 'NOT_FOUND' using errcode = 'P0001'; end if;
  if lk is not null and (length(lk) > 500 or lk !~ '^https://[^[:space:]]+$') then
    raise exception 'BAD_LINK: the link must start with https:// and have no spaces (500 characters at most)' using errcode = 'P0001'; end if;
  update students set online_link = lk where id = p_student and org_id = p_org;
  if lk is distinct from old then
    insert into audit_log(org_id, actor, action, table_name, row_id, before, after)
    values (p_org, auth.uid(), 'staff_set_student_link', 'students', p_student::text, jsonb_build_object('online_link', old), jsonb_build_object('online_link', lk));
  end if;
  return jsonb_build_object('online_link', lk);
end $$;
revoke all on function public.staff_set_student_link(uuid, uuid, text) from public, anon;
grant execute on function public.staff_set_student_link(uuid, uuid, text) to authenticated;

-- ---------------------------------------------------------------- 9. a tutor's own lessons' online links (tutor side; no money, no parent contact)
-- Only the caller's OWN lessons (taught_by is their active membership) in a centre, for at most 62 days. A tutor with no lessons in the range, a
-- parent or a stranger gets an empty list, never an error that would show whether a lesson exists.
create or replace function public.tutor_lesson_links(p_from date, p_to date) returns table(lesson_id uuid, online_link text)
language plpgsql stable security definer set search_path = public as $$
begin
  if auth.uid() is null then raise exception 'NOT_FOUND' using errcode = 'P0001'; end if;
  if p_from is null or p_to is null or p_to < p_from or p_to - p_from > 62 then
    raise exception 'BAD_RANGE: ask for at most 62 days' using errcode = 'P0001'; end if;
  return query
    select l.id, s.online_link
      from lessons l
      join memberships m on m.id = l.taught_by and m.org_id = l.org_id and m.user_id = auth.uid() and m.status = 'active'
      join organisations o on o.id = l.org_id and o.kind = 'centre'
      join students s on s.id = l.student_id and s.org_id = l.org_id
     where l.lesson_date between p_from and p_to and s.online_link is not null;
end $$;
revoke all on function public.tutor_lesson_links(date, date) from public, anon;
grant execute on function public.tutor_lesson_links(date, date) to authenticated;

-- ---------------------------------------------------------------- 10. staff_timetable: the lesson's online link is now the student's link (it was always null)
-- Same arguments, same columns, same rules as migration_staff_timetable.sql; only 'online_link' changed. Undo puts the earlier text back.
create or replace function public.staff_timetable(p_org uuid, p_from date, p_to date, p_tutor uuid default null, p_branch uuid default null,
                                                  p_student uuid default null, p_page int default 1, p_notutor boolean default false,
                                                  p_size int default 50) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare today date := staff_attendance_gate(p_org, false);
        pg int := coalesce(p_page, 1); sz int := coalesce(p_size, 50); nt boolean := coalesce(p_notutor, false);
        cnt jsonb; rows jsonb; tutors jsonb; branches jsonb; studs jsonb; hols jsonb; total int; n_studs int;
begin
  if p_from is null or p_to is null or p_to < p_from or p_to - p_from > 62 then
    raise exception 'BAD_RANGE: ask for at most 62 days' using errcode = 'P0001'; end if;
  if pg < 1 or pg > 100000 then raise exception 'BAD_PAGE: no such page' using errcode = 'P0001'; end if;
  if sz < 1 or sz > 100 then raise exception 'BAD_PAGE: ask for 1 to 100 lessons at a time' using errcode = 'P0001'; end if;
  if p_tutor is not null and not exists (select 1 from memberships m where m.id = p_tutor and m.org_id = p_org) then
    raise exception 'NOT_FOUND' using errcode = 'P0001'; end if;
  if p_branch is not null and not exists (select 1 from branches b where b.id = p_branch and b.org_id = p_org) then
    raise exception 'NOT_FOUND' using errcode = 'P0001'; end if;
  if p_student is not null and not exists (select 1 from students s where s.id = p_student and s.org_id = p_org) then
    raise exception 'NOT_FOUND' using errcode = 'P0001'; end if;

  -- holidays touching the range (a branch's own holiday is labelled with the branch, so it can't be mistaken for the whole centre's)
  select coalesce(jsonb_agg(jsonb_build_object('id', h.id, 'name', h.name, 'starts_on', h.starts_on, 'ends_on', h.ends_on,
                                               'branch_id', h.branch_id, 'branch_name', b.name) order by h.starts_on, h.name, h.id), '[]'::jsonb)
    into hols
    from holidays h left join branches b on b.id = h.branch_id and b.org_id = h.org_id
   where h.org_id = p_org and h.starts_on <= p_to and h.ends_on >= p_from
     and (p_branch is null or h.branch_id is null or h.branch_id = p_branch);

  with base as (
    select l.id, l.lesson_date, l.start_time, l.end_time, l.subject, l.status, l.attendance, l.trial, l.postponed, l.session_id, l.taught_by,
           s.id as sid, s.name as sname, s.level as slevel, s.online_link as slink, t.status as tstatus, t.display_name as tname,
           (l.status = 'cancelled' and l.attendance is null) as closed,
           (l.taught_by is null and l.status <> 'cancelled') as no_tutor,
           (select h.name from holidays h where h.org_id = p_org and l.lesson_date between h.starts_on and h.ends_on
               and (h.branch_id is null or h.branch_id = p_branch) order by h.starts_on, h.name limit 1) as holiday
      from lessons l
      join students s on s.id = l.student_id and s.org_id = l.org_id
      left join memberships t on t.id = l.taught_by and t.org_id = l.org_id
     where l.org_id = p_org and l.lesson_date between p_from and p_to
       and (p_tutor is null or l.taught_by = p_tutor) and (p_student is null or l.student_id = p_student)),
  d as (
    select base.*, case when closed then 'cancelled' when attendance is not null then 'marked' when lesson_date > today then 'future' else 'open' end as state
      from base),
  c as (select count(*)::int as n_all, (count(*) filter (where no_tutor))::int as n_notutor,
               (count(*) filter (where status = 'cancelled'))::int as n_cancelled, (count(*) filter (where holiday is not null))::int as n_holiday from d),
  pg_rows as (
    select * from d where (not nt or no_tutor)
     order by lesson_date, start_time, sname, id
     limit sz offset (pg - 1) * sz)
  select (select row_to_json(c) from c)::jsonb,
         coalesce((select jsonb_agg(jsonb_build_object(
           'lesson_id', id, 'lesson_date', lesson_date, 'start_time', start_time, 'end_time', end_time,
           'minutes', (extract(epoch from (end_time - start_time)) / 60)::int,
           'student_id', sid, 'student_name', sname, 'student_level', slevel, 'subject', subject,
           'tutor_id', taught_by,
           'tutor_name', case when taught_by is null then null when tstatus is null or tstatus = 'disabled' then 'Former tutor' else coalesce(tname, 'Tutor') end,
           'no_tutor', no_tutor, 'trial', trial, 'attendance', attendance, 'state', state,
           'cancelled', (status = 'cancelled'), 'postponed', postponed, 'holiday', holiday, 'session_id', session_id,
           'online_link', slink)
           order by lesson_date, start_time, sname, id) from pg_rows), '[]'::jsonb)
    into cnt, rows;
  total := case when nt then (cnt->>'n_notutor')::int else (cnt->>'n_all')::int end;

  select coalesce(jsonb_agg(jsonb_build_object('id', m.id, 'name', m.display_name) order by m.display_name, m.id), '[]'::jsonb) into tutors
    from memberships m where m.org_id = p_org and m.role = 'tutor' and m.status in ('active', 'invited');
  select coalesce(jsonb_agg(jsonb_build_object('id', b.id, 'name', b.name) order by b.name, b.id), '[]'::jsonb) into branches
    from branches b where b.org_id = p_org;
  -- who has a lesson in this range (for the student filter): at most 300 names, and the page says so when there are more
  select count(distinct l.student_id) into n_studs from lessons l where l.org_id = p_org and l.lesson_date between p_from and p_to;
  select coalesce(jsonb_agg(jsonb_build_object('id', x.id, 'name', x.name) order by x.name, x.id), '[]'::jsonb) into studs
    from (select s.id, s.name from students s
           where s.org_id = p_org and exists (select 1 from lessons l where l.org_id = p_org and l.student_id = s.id and l.lesson_date between p_from and p_to)
           order by s.name, s.id limit 300) x;

  return jsonb_build_object('today', today, 'page', pg, 'size', sz, 'total', total, 'counts', cnt, 'holidays', hols,
                            'tutors', tutors, 'branches', branches, 'students', studs, 'students_more', n_studs > 300, 'rows', rows);
end $$;

revoke all on function public.staff_timetable(uuid, date, date, uuid, uuid, uuid, int, boolean, int) from public, anon;
grant execute on function public.staff_timetable(uuid, date, date, uuid, uuid, uuid, int, boolean, int) to authenticated;

-- #####################################################################################################
-- ### PART 8 of 21 — reassign / cover a lesson
-- ### source branch: claude/t3-8-reassign   file: db/migration_staff_reassign.sql   undo: db/migration_staff_reassign_down.sql
-- ### (if an error appears, search this file for the nearest "### PART" line above the error line: that is the part that failed)
-- #####################################################################################################
-- =====================================================================================================
-- T3 step 8 — reassign a lesson to another tutor, or cover it with a replacement          undo: migration_staff_reassign_down.sql
-- =====================================================================================================
-- Needs migration_staff_slots.sql (it reuses staff_slots_gate and student_tutors) and everything before it (lessons.taught_by / session_id, org settings).
--
-- WHAT IT ADDS
--   lessons.covered_for            who the lesson was MEANT for (memberships.id) when someone else is covering it; null = nobody is covering
--   lesson_locked_reason           internal: why a lesson can no longer change hands (marked / cancelled / paid / invoiced), or null
--   staff_reassign_lesson          write  give one lesson (or the whole class of that day) to another tutor: mode 'reassign' or 'cover'
--   staff_timetable                replaced (same arguments): rows gain covered_for_id / covered_for_name / can_reassign, the answer gains can_edit,
--                                  replacements_allowed, and each tutor says whether they are active
--
-- THE TWO MODES, in plain words
--   cover      a ONE-OFF replacement. The lesson's tutor changes; the weekly slot and the student's assigned tutors do NOT, so next week's lesson is
--              still the original tutor's. lessons.covered_for keeps who it was meant for, so the Timetable says "Covered by X" and the audit log says
--              who covered for whom and why. Handing it back to the original tutor clears covered_for.
--   reassign   the lesson permanently goes to the new tutor (covered_for is cleared: nobody is "covering"). The weekly slot is left alone (change it
--              in Weekly slots). The caller may ALSO choose, as an explicit second choice, to move the student's assigned-tutor link
--              (student_tutors) from the old tutor to the new one. A cover never touches that link and refuses the choice.
--   Either way the lesson moves from the original tutor's tutor_my_lessons list to the new tutor's (that function reads lessons.taught_by and is
--   unchanged), and attendance and pay follow the tutor who taught it.
--
-- THE CENTRE'S OWN RULE: lessons.replacement_tutors (a toggle in the sign-up wizard, default ON, read as of TODAY, a process rule)
--   on   staff may give a lesson that already has a tutor to someone else.
--   off  that is refused with a plain message ("this centre doesn't allow replacement tutors"). A lesson with NO tutor yet can still be given its
--        first tutor: that is not a replacement (the same line lessons_taught_by_guard already draws for anyone writing the table).
--   There is no third value today (the wizard offers a toggle). Nothing is marked "soon": both values are built.
--
-- WHO MAY CALL: an active OWNER or STAFF member of this centre with manage_timetable (owners always). Staff without it: NOT_ALLOWED. A tutor, a
--   parent, switched-off staff, a stranger, a solo organisation, an unknown id: the same NOT_FOUND, so ids can't be probed. Tutors have no
--   function that moves a lesson to another tutor (T6 tutors only schedule their own).
--
-- INTEGRITY (fixed, not a centre choice)
--   * never a lesson that is already marked (it stays with the tutor who taught it), cancelled, paid, or on an invoice;
--   * the new tutor must be an ACTIVE member of THIS centre (owner, staff or tutor);
--   * a class (lessons sharing a session_id) moves together, all or nothing; if any lesson of it is locked nothing moves;
--   * a reason (up to 500 characters) is required whenever a lesson that already has a tutor changes hands; it goes in the audit log.
-- Run on the DEV project first. Safe to run twice.
-- =====================================================================================================

-- ---------------------------------------------------------------- the column
alter table public.lessons add column if not exists covered_for uuid;
do $$ begin
  if not exists (select 1 from pg_constraint where conname = 'lessons_covered_for_same_org') then
    -- same organisation only; if that person is removed the lesson keeps its organisation (set null on covered_for ONLY)
    alter table public.lessons add constraint lessons_covered_for_same_org
      foreign key (covered_for, org_id) references public.memberships(id, org_id) on delete set null (covered_for);
  end if;
end $$;
create index if not exists lessons_covered_for on public.lessons(covered_for) where covered_for is not null;

-- ---------------------------------------------------------------- why a lesson can't change hands (null = it can)
-- Internal helper; the browser can't call it. Paid is the Ledger's flag; "invoiced" = a current (not replaced) invoice lists the lesson.
create or replace function public.lesson_locked_reason(p_lesson uuid) returns text
language sql stable security definer set search_path = public as $$
  select case
    when l.attendance is not null then 'MARKED'
    when l.status = 'cancelled' then 'CANCELLED'
    when l.paid then 'PAID'
    when exists (select 1 from invoices i where i.org_id = l.org_id and jsonb_typeof(i.data -> 'lesson_ids') = 'array'
                    and i.data -> 'lesson_ids' @> to_jsonb(l.id::text) and (i.data ->> 'replaced_by') is null) then 'INVOICED'
  end from lessons l where l.id = p_lesson $$;
revoke all on function public.lesson_locked_reason(uuid) from public, anon, authenticated;

-- ---------------------------------------------------------------- staff_reassign_lesson
create or replace function public.staff_reassign_lesson(p_lesson uuid, p_new_tutor uuid, p_mode text, p_reason text default null,
                                                        p_update_links boolean default false) returns jsonb
language plpgsql security definer set search_path = public as $$
declare l lessons; cl lessons; today date; md text := lower(trim(coalesce(p_mode, ''))); why text := nullif(trim(coalesce(p_reason, '')), '');
        nt memberships; cfg jsonb; allowed boolean; ids uuid[]; locked text; orig uuid; new_cf uuid; old_tutor uuid;
        sid uuid; ended int := 0; added int := 0; n_ended int; before_j jsonb := '[]'::jsonb; link_ids uuid[];
begin
  if auth.uid() is null then raise exception 'NOT_FOUND' using errcode = 'P0001'; end if;
  select * into l from lessons where id = p_lesson;
  if not found then raise exception 'NOT_FOUND' using errcode = 'P0001'; end if;
  today := staff_slots_gate(l.org_id, true);                                            -- NOT_FOUND for strangers, NOT_ALLOWED without manage_timetable

  if md not in ('reassign', 'cover') then raise exception 'BAD_MODE: choose cover or reassign' using errcode = 'P0001'; end if;
  if p_new_tutor is null then raise exception 'PICK_TUTOR: choose who will teach this lesson' using errcode = 'P0001'; end if;
  if why is not null and length(why) > 500 then raise exception 'TOO_LONG: keep the reason under 500 characters' using errcode = 'P0001'; end if;
  if coalesce(p_update_links, false) and md = 'cover' then
    raise exception 'LINK_NOT_FOR_COVER: a cover is one lesson only, so it never changes who a student is assigned to' using errcode = 'P0001'; end if;

  select * into nt from memberships m where m.id = p_new_tutor and m.org_id = l.org_id and m.role in ('tutor', 'staff', 'owner') and m.status = 'active';
  if not found then raise exception 'NOT_AVAILABLE: that person can''t be given lessons at this centre (they must be an active member here)' using errcode = 'P0001'; end if;
  if l.taught_by is not distinct from p_new_tutor then
    raise exception 'NO_CHANGE: that tutor already teaches this lesson' using errcode = 'P0001'; end if;

  if l.taught_by is null then
    if md = 'cover' then raise exception 'NO_TUTOR_TO_COVER: this lesson has no tutor yet, so there is nobody to cover for. Use Assign instead' using errcode = 'P0001'; end if;
  else
    -- a lesson that already has a tutor changing hands is a replacement: the centre's own rule decides (read as of today)
    cfg := org_settings_on(l.org_id, today) #> '{lessons,replacement_tutors}';
    allowed := case when jsonb_typeof(cfg) = 'boolean' then (cfg #>> '{}')::boolean else true end;      -- missing = on (the default)
    if not allowed then
      raise exception 'REPLACEMENT_OFF: this centre doesn''t allow replacement tutors. An owner can switch this on in the centre settings' using errcode = 'P0001'; end if;
    if why is null then raise exception 'REASON_REQUIRED: say why this lesson is changing tutor. It is kept on record' using errcode = 'P0001'; end if;
  end if;

  -- the lesson, or the whole class of that day (lessons sharing a session_id): all or nothing
  select coalesce(array_agg(x.id order by x.id), array[l.id]) into ids from lessons x
   where x.org_id = l.org_id and (x.id = l.id or (l.session_id is not null and x.session_id = l.session_id));
  perform 1 from lessons x where x.id = any(ids) order by x.id for update;
  foreach sid in array ids loop
    locked := lesson_locked_reason(sid);
    if locked is not null then
      raise exception '%', case locked
        when 'MARKED'    then 'ALREADY_MARKED: this lesson is already marked, so it stays with the tutor who taught it'
        when 'CANCELLED' then 'CANCELLED: this lesson was cancelled'
        when 'PAID'      then 'PAID: this lesson is already paid, so it can''t change hands'
        else                  'INVOICED: this lesson is on an invoice, so it can''t change hands' end
        || case when array_length(ids, 1) > 1 then ' (it is part of a class that moves together)' else '' end using errcode = 'P0001';
    end if;
  end loop;

  -- move them
  for cl in select * from lessons x where x.id = any(ids) order by x.id loop
    before_j := before_j || jsonb_build_object('lesson_id', cl.id, 'taught_by', cl.taught_by, 'covered_for', cl.covered_for);
    if md = 'cover' then
      orig := coalesce(cl.covered_for, cl.taught_by);                                    -- who it was meant for stays the same however often it is covered
      new_cf := case when orig is distinct from p_new_tutor then orig end;              -- handed back to the original tutor = nobody is covering
    else new_cf := null; end if;
    update lessons set taught_by = p_new_tutor, covered_for = new_cf where id = cl.id;
  end loop;

  -- reassign only, and only when asked: the student's assigned-tutor link follows (the old tutor's ends, the new tutor's starts)
  if coalesce(p_update_links, false) then
    for sid in select distinct x.student_id from lessons x where x.id = any(ids) loop
      old_tutor := (select (e ->> 'taught_by')::uuid from jsonb_array_elements(before_j) e
                     join lessons y on y.id = (e ->> 'lesson_id')::uuid where y.student_id = sid limit 1);
      if old_tutor is not null then
        update student_tutors set active = false, until = today where org_id = l.org_id and student_id = sid and membership_id = old_tutor and active;
        get diagnostics n_ended = row_count; ended := ended + n_ended;
      end if;
      if not exists (select 1 from student_tutors x where x.org_id = l.org_id and x.student_id = sid and x.membership_id = p_new_tutor and x.active) then
        insert into student_tutors(org_id, student_id, membership_id, since, created_by) values (l.org_id, sid, p_new_tutor, today, auth.uid());
        added := added + 1;
      end if;
    end loop;
  end if;

  insert into audit_log(org_id, actor, action, table_name, row_id, before, after)
  values (l.org_id, auth.uid(), 'staff_reassign_lesson', 'lessons', l.id::text,
          jsonb_build_object('lessons', before_j),
          jsonb_build_object('mode', md, 'new_tutor', p_new_tutor, 'new_tutor_name', nt.display_name, 'lessons', to_jsonb(ids), 'reason', why,
                             'covered_for', (select covered_for from lessons where id = l.id),
                             'links_updated', coalesce(p_update_links, false), 'links_ended', ended, 'links_added', added));
  return jsonb_build_object('lesson_id', l.id, 'lessons', array_length(ids, 1), 'mode', md, 'tutor_id', p_new_tutor,
                            'tutor_name', coalesce(nt.display_name, 'Tutor'), 'covered_for', (select covered_for from lessons where id = l.id),
                            'links_ended', ended, 'links_added', added);
end $$;
revoke all on function public.staff_reassign_lesson(uuid, uuid, text, text, boolean) from public, anon;
grant execute on function public.staff_reassign_lesson(uuid, uuid, text, text, boolean) to authenticated;

-- ---------------------------------------------------------------- staff_timetable: who is covering, and whether the lesson can still change hands
-- Same arguments and rules as migration_staff_slots.sql. New: per row covered_for_id / covered_for_name ('Former tutor' when that person has been
-- switched off) and can_reassign (not marked, cancelled, paid or invoiced: a yes/no, no money); on the answer can_edit (the caller has
-- manage_timetable) and replacements_allowed (the centre's lessons.replacement_tutors, as of today); each tutor says whether they are active.
create or replace function public.staff_timetable(p_org uuid, p_from date, p_to date, p_tutor uuid default null, p_branch uuid default null,
                                                  p_student uuid default null, p_page int default 1, p_notutor boolean default false,
                                                  p_size int default 50) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare today date := staff_attendance_gate(p_org, false); can_ed boolean := org_can(p_org, 'manage_timetable'); rep_on boolean;
        pg int := coalesce(p_page, 1); sz int := coalesce(p_size, 50); nt boolean := coalesce(p_notutor, false);
        cnt jsonb; rows jsonb; tutors jsonb; branches jsonb; studs jsonb; hols jsonb; total int; n_studs int;
begin
  if p_from is null or p_to is null or p_to < p_from or p_to - p_from > 62 then
    raise exception 'BAD_RANGE: ask for at most 62 days' using errcode = 'P0001'; end if;
  if pg < 1 or pg > 100000 then raise exception 'BAD_PAGE: no such page' using errcode = 'P0001'; end if;
  if sz < 1 or sz > 100 then raise exception 'BAD_PAGE: ask for 1 to 100 lessons at a time' using errcode = 'P0001'; end if;
  if p_tutor is not null and not exists (select 1 from memberships m where m.id = p_tutor and m.org_id = p_org) then
    raise exception 'NOT_FOUND' using errcode = 'P0001'; end if;
  if p_branch is not null and not exists (select 1 from branches b where b.id = p_branch and b.org_id = p_org) then
    raise exception 'NOT_FOUND' using errcode = 'P0001'; end if;
  if p_student is not null and not exists (select 1 from students s where s.id = p_student and s.org_id = p_org) then
    raise exception 'NOT_FOUND' using errcode = 'P0001'; end if;

  rep_on := case when jsonb_typeof(org_settings_on(p_org, today) #> '{lessons,replacement_tutors}') = 'boolean'
                 then (org_settings_on(p_org, today) #>> '{lessons,replacement_tutors}')::boolean else true end;      -- missing = on

  -- holidays touching the range (a branch's own holiday is labelled with the branch, so it can't be mistaken for the whole centre's)
  select coalesce(jsonb_agg(jsonb_build_object('id', h.id, 'name', h.name, 'starts_on', h.starts_on, 'ends_on', h.ends_on,
                                               'branch_id', h.branch_id, 'branch_name', b.name) order by h.starts_on, h.name, h.id), '[]'::jsonb)
    into hols
    from holidays h left join branches b on b.id = h.branch_id and b.org_id = h.org_id
   where h.org_id = p_org and h.starts_on <= p_to and h.ends_on >= p_from
     and (p_branch is null or h.branch_id is null or h.branch_id = p_branch);

  with base as (
    select l.id, l.lesson_date, l.start_time, l.end_time, l.subject, l.status, l.attendance, l.trial, l.postponed, l.session_id, l.taught_by, l.covered_for,
           s.id as sid, s.name as sname, s.level as slevel, s.online_link as slink, t.status as tstatus, t.display_name as tname, cf.status as cfstatus, cf.display_name as cfname,
           (lesson_locked_reason(l.id) is null) as can_re,
           (l.status = 'cancelled' and l.attendance is null) as closed,
           (l.taught_by is null and l.status <> 'cancelled') as no_tutor,
           (select h.name from holidays h where h.org_id = p_org and l.lesson_date between h.starts_on and h.ends_on
               and (h.branch_id is null or h.branch_id = p_branch) order by h.starts_on, h.name limit 1) as holiday
      from lessons l
      join students s on s.id = l.student_id and s.org_id = l.org_id
      left join memberships t on t.id = l.taught_by and t.org_id = l.org_id
      left join memberships cf on cf.id = l.covered_for and cf.org_id = l.org_id
     where l.org_id = p_org and l.lesson_date between p_from and p_to
       and (p_tutor is null or l.taught_by = p_tutor) and (p_student is null or l.student_id = p_student)),
  d as (
    select base.*, case when closed then 'cancelled' when attendance is not null then 'marked' when lesson_date > today then 'future' else 'open' end as state
      from base),
  c as (select count(*)::int as n_all, (count(*) filter (where no_tutor))::int as n_notutor,
               (count(*) filter (where status = 'cancelled'))::int as n_cancelled, (count(*) filter (where holiday is not null))::int as n_holiday from d),
  pg_rows as (
    select * from d where (not nt or no_tutor)
     order by lesson_date, start_time, sname, id
     limit sz offset (pg - 1) * sz)
  select (select row_to_json(c) from c)::jsonb,
         coalesce((select jsonb_agg(jsonb_build_object(
           'lesson_id', id, 'lesson_date', lesson_date, 'start_time', start_time, 'end_time', end_time,
           'minutes', (extract(epoch from (end_time - start_time)) / 60)::int,
           'student_id', sid, 'student_name', sname, 'student_level', slevel, 'subject', subject,
           'tutor_id', taught_by,
           'tutor_name', case when taught_by is null then null when tstatus is null or tstatus = 'disabled' then 'Former tutor' else coalesce(tname, 'Tutor') end,
           'no_tutor', no_tutor, 'trial', trial, 'attendance', attendance, 'state', state,
           'cancelled', (status = 'cancelled'), 'postponed', postponed, 'holiday', holiday, 'session_id', session_id,
           'online_link', slink,
           'covered_for_id', covered_for,
           'covered_for_name', case when covered_for is null then null when cfstatus is null or cfstatus = 'disabled' then 'Former tutor' else coalesce(cfname, 'Tutor') end,
           'can_reassign', can_re)
           order by lesson_date, start_time, sname, id) from pg_rows), '[]'::jsonb)
    into cnt, rows;
  total := case when nt then (cnt->>'n_notutor')::int else (cnt->>'n_all')::int end;

  select coalesce(jsonb_agg(jsonb_build_object('id', m.id, 'name', m.display_name, 'active', (m.status = 'active')) order by m.display_name, m.id), '[]'::jsonb) into tutors
    from memberships m where m.org_id = p_org and m.role = 'tutor' and m.status in ('active', 'invited');
  select coalesce(jsonb_agg(jsonb_build_object('id', b.id, 'name', b.name) order by b.name, b.id), '[]'::jsonb) into branches
    from branches b where b.org_id = p_org;
  -- who has a lesson in this range (for the student filter): at most 300 names, and the page says so when there are more
  select count(distinct l.student_id) into n_studs from lessons l where l.org_id = p_org and l.lesson_date between p_from and p_to;
  select coalesce(jsonb_agg(jsonb_build_object('id', x.id, 'name', x.name) order by x.name, x.id), '[]'::jsonb) into studs
    from (select s.id, s.name from students s
           where s.org_id = p_org and exists (select 1 from lessons l where l.org_id = p_org and l.student_id = s.id and l.lesson_date between p_from and p_to)
           order by s.name, s.id limit 300) x;

  return jsonb_build_object('today', today, 'can_edit', can_ed, 'replacements_allowed', rep_on, 'page', pg, 'size', sz, 'total', total, 'counts', cnt, 'holidays', hols,
                            'tutors', tutors, 'branches', branches, 'students', studs, 'students_more', n_studs > 300, 'rows', rows);
end $$;

revoke all on function public.staff_timetable(uuid, date, date, uuid, uuid, uuid, int, boolean, int) from public, anon;
grant execute on function public.staff_timetable(uuid, date, date, uuid, uuid, uuid, int, boolean, int) to authenticated;

-- #####################################################################################################
-- ### PART 9 of 21 — tutor Schedule tab (read only)
-- ### source branch: claude/t6-1-tutor-schedule   file: db/migration_tutor_schedule.sql   undo: db/migration_tutor_schedule_down.sql
-- ### (if an error appears, search this file for the nearest "### PART" line above the error line: that is the part that failed)
-- #####################################################################################################
-- =====================================================================================================
-- T6 step 1 — the tutor's read-only Schedule: my week, and my weekly slots                  undo: migration_tutor_schedule_down.sql
-- =====================================================================================================
-- Needs migration_staff_reassign.sql (and everything before it: lessons.taught_by, covered_for, recurring_slots.taught_by, students.online_link, holidays).
-- Adds NO columns and NO tables. Two read-only functions for centre tutors; nothing is written, nothing existing changes.
--
--   tutor_my_schedule(from, to)   read   MY lessons in a date range (at most 62 days), with the whole-centre holidays that fall in it
--   tutor_my_slots()              read   MY weekly slots (day, time, student), the ones staff assigned to me
--
-- WHO MAY CALL: a person with an ACTIVE tutor membership in a CENTRE. Anyone else (staff or owner of a centre, a parent, a solo organisation's
-- owner, a switched-off tutor, a stranger, not signed in) gets NOT_FOUND, the same word as the rest of the tutor functions, so nothing can be
-- probed. A tutor sees ONLY their own membership's rows, in the centre(s) where they are an active tutor.
--
-- WHAT A TUTOR NEVER SEES (the rule of tutor_my_lessons, kept here): no rate, price, amount, paid flag, compensation, charge note or *_cents.
-- The two functions below name every column they return; they never use `l.*` / `sl.*`, and no money column is read at all. tests/sql/tutor_schedule_test.sql
-- checks this three ways: the returned keys, the function text (no money word in it), and a lesson/slot whose money columns hold marker values.
-- The student's parent contact comes back only when the centre's existing setting `lessons.tutors_see_parent_contact` is on (default off).
--
-- WHAT A ROW SAYS (plain words): date, start, end, student name and level, subject, the student's online link (if staff set one), trial, the
-- attendance mark (null = not marked yet), cancelled, postponed (moved from its usual day), covering (someone else's lesson I am covering),
-- and `holiday` = the name of a whole-centre holiday that day. Branch holidays are not shown: slots and students carry no branch.
-- `timetable_editing` is the centre's setting 'who edits the timetable' (admin_only today). In this step it only decides which note the screen
-- shows: nothing here lets a tutor change anything (that is T6 step 2 onward).
-- Run on the DEV project first. Safe to run twice.
-- =====================================================================================================

-- ---------------------------------------------------------------- 1. my lessons in a range, plus holidays
drop function if exists public.tutor_my_schedule(date, date);
create or replace function public.tutor_my_schedule(p_from date, p_to date) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare orgs jsonb; lessons jsonb; hols jsonb; today date;
begin
  if auth.uid() is null then raise exception 'NOT_FOUND' using errcode = 'P0001'; end if;
  if not exists (select 1 from memberships m join organisations o on o.id = m.org_id and o.kind = 'centre'
                  where m.user_id = auth.uid() and m.role = 'tutor' and m.status = 'active') then
    raise exception 'NOT_FOUND' using errcode = 'P0001'; end if;
  if p_from is null or p_to is null or p_to < p_from or p_to - p_from > 62 then
    raise exception 'BAD_RANGE: ask for at most 62 days' using errcode = 'P0001'; end if;

  select jsonb_agg(jsonb_build_object('org_id', o.id, 'name', o.trading_name, 'today', (now() at time zone o.timezone)::date,
                                      'timetable_editing', coalesce(org_settings_on(o.id, current_date) #>> '{lessons,timetable_editing}', 'admin_only'),
                                      'can_edit', false) order by o.trading_name, o.id),
         min((now() at time zone o.timezone)::date)
    into orgs, today
    from memberships m join organisations o on o.id = m.org_id and o.kind = 'centre'
   where m.user_id = auth.uid() and m.role = 'tutor' and m.status = 'active';

  select coalesce(jsonb_agg(jsonb_build_object(
           'lesson_id', l.id, 'org_id', l.org_id, 'org_name', o.trading_name,
           'student_id', s.id, 'student_name', s.name, 'student_level', s.level,
           'parent_contact', case when coalesce((org_settings_on(l.org_id, current_date) #>> '{lessons,tutors_see_parent_contact}')::boolean, false) then s.contact end,
           'lesson_date', l.lesson_date, 'start_time', l.start_time, 'end_time', l.end_time,
           'minutes', (extract(epoch from (l.end_time - l.start_time)) / 60)::int, 'subject', l.subject,
           'trial', l.trial, 'attendance', l.attendance, 'status', l.status, 'cancelled', (l.status = 'cancelled'),
           'postponed', l.postponed, 'covering', (l.covered_for is not null), 'online_link', s.online_link,
           'holiday', (select h.name from holidays h where h.org_id = l.org_id and h.branch_id is null
                        and l.lesson_date between h.starts_on and h.ends_on order by h.starts_on, h.name limit 1)
         ) order by l.lesson_date, l.start_time, s.name, l.id), '[]'::jsonb)
    into lessons
    from lessons l
    join memberships m on m.id = l.taught_by and m.org_id = l.org_id and m.user_id = auth.uid() and m.role = 'tutor' and m.status = 'active'
    join organisations o on o.id = l.org_id and o.kind = 'centre'
    join students s on s.id = l.student_id and s.org_id = l.org_id
   where l.lesson_date between p_from and p_to;

  select coalesce(jsonb_agg(jsonb_build_object('org_id', h.org_id, 'name', h.name, 'starts_on', h.starts_on, 'ends_on', h.ends_on)
                            order by h.starts_on, h.name, h.id), '[]'::jsonb)
    into hols
    from holidays h
   where h.branch_id is null and h.starts_on <= p_to and h.ends_on >= p_from
     and exists (select 1 from memberships m join organisations o on o.id = m.org_id and o.kind = 'centre'
                  where m.org_id = h.org_id and m.user_id = auth.uid() and m.role = 'tutor' and m.status = 'active');

  return jsonb_build_object('today', today, 'from', p_from, 'to', p_to, 'orgs', orgs, 'lessons', lessons, 'holidays', hols);
end $$;

-- ---------------------------------------------------------------- 2. my weekly slots
-- One row per student of an ACTIVE weekly slot that staff gave to me (a group class is several rows sharing a session_key). weekday 0 = Monday … 6 = Sunday,
-- like the Planner. A student whose lessons have ended (students.end_date, inclusive) is not listed.
drop function if exists public.tutor_my_slots();
create or replace function public.tutor_my_slots()
returns table(slot_id uuid, org_id uuid, org_name text, weekday int, start_time time, end_time time, subject text,
              student_id uuid, student_name text, student_level text, session_key uuid, timetable_editing text)
language plpgsql stable security definer set search_path = public as $$
begin
  if auth.uid() is null then raise exception 'NOT_FOUND' using errcode = 'P0001'; end if;
  if not exists (select 1 from memberships m join organisations o on o.id = m.org_id and o.kind = 'centre'
                  where m.user_id = auth.uid() and m.role = 'tutor' and m.status = 'active') then
    raise exception 'NOT_FOUND' using errcode = 'P0001'; end if;
  return query
    select sl.id, sl.org_id, o.trading_name, sl.weekday::int, sl.start_time, sl.end_time, sl.subject,
           s.id, s.name, s.level, sl.session_key,
           coalesce(org_settings_on(sl.org_id, current_date) #>> '{lessons,timetable_editing}', 'admin_only')
      from recurring_slots sl
      join memberships m on m.id = sl.taught_by and m.org_id = sl.org_id and m.user_id = auth.uid() and m.role = 'tutor' and m.status = 'active'
      join organisations o on o.id = sl.org_id and o.kind = 'centre'
      join students s on s.id = sl.student_id and s.org_id = sl.org_id
     where sl.active and (s.end_date is null or s.end_date >= (now() at time zone o.timezone)::date)
     order by sl.weekday, sl.start_time, s.name, sl.id;
end $$;

-- ---------------------------------------------------------------- who may call
do $$
declare f text;
begin
  foreach f in array array['tutor_my_schedule(date,date)', 'tutor_my_slots()'] loop
    execute format('revoke all on function public.%s from public, anon', f);
    execute format('grant execute on function public.%s to authenticated', f);
  end loop;
end $$;

-- #####################################################################################################
-- ### PART 10 of 21 — centre money settings + validator
-- ### source branch: claude/t4-s0-settings   file: db/migration_money_settings.sql   undo: db/migration_money_settings_down.sql
-- ### (if an error appears, search this file for the nearest "### PART" line above the error line: that is the part that failed)
-- #####################################################################################################
-- T4 S0: centre-money settings. Replaces org_validate_settings() so every new option is checked on save (deposit, late fee,
-- tutor pay percentage, trial charging, class type, opening invoice number). Optional keys: settings saved before this still pass.
-- Safe to run twice. Undo: db/migration_money_settings_down.sql. Order: ... staff_timetable -> money_settings.
-- Nothing reads these settings yet (later T4 steps do); this only stops bad values being saved.
create or replace function public.org_validate_settings(s jsonb) returns void language plpgsql immutable set search_path = public as $$
declare k text; v jsonb; r record;
begin
  if coalesce((s->>'schema_version')::int, 0) <> 1 then raise exception 'Unknown settings schema_version'; end if;
  foreach k in array array['profile','calendar','billing','invoicing','payments','lessons','tutor_pay','data'] loop
    if jsonb_typeof(s->k) is distinct from 'object' then raise exception 'Settings section "%" is missing', k; end if;
  end loop;
  if (s#>>'{profile,gst_registered}')::boolean and not ((s#>>'{profile,gst_rate_bp}')::int between 0 and 5000) then
    raise exception 'GST rate must be between 0%% and 50%%'; end if;
  if s#>>'{billing,model}' not in ('prepaid_packages','fixed_in_advance','postpaid_lessons','pay_per_lesson') then
    raise exception 'Unknown billing model'; end if;
  if s#>>'{tutor_pay,mode}' not in ('off','report','full') then raise exception 'Unknown tutor pay mode'; end if;
  if s#>>'{tutor_pay,payable_when}' not in ('taught','parent_paid') then raise exception 'Unknown payable rule'; end if;
  if s#>>'{invoicing,grouping}' not in ('family','student') then raise exception 'Unknown invoice grouping'; end if;
  if s#>>'{lessons,attendance_by}' not in ('tutor','admin') then raise exception 'Unknown attendance setting'; end if;
  if s#>>'{lessons,cancellations_marked_by}' not in ('admin','tutor') then raise exception 'Unknown cancellation setting'; end if;
  if s#>>'{lessons,compensation_entered_by}' not in ('admin','tutor') then raise exception 'Unknown compensation setting'; end if;
  if s#>>'{lessons,trials_flagged_by}' not in ('admin','tutor') then raise exception 'Unknown trial setting'; end if;
  if s#>>'{lessons,attendance_window_days}' is not null and (s#>>'{lessons,attendance_window_days}' !~ '^[0-9]{1,3}$'
     or (s#>>'{lessons,attendance_window_days}')::int not between 1 and 60) then raise exception 'Attendance window must be 1-60 days'; end if;
  if not (s#>'{payments,modes}' ?| array['manual_paynow','statement_matching','hitpay','stripe']) then
    raise exception 'Pick at least one way for parents to pay'; end if;
  -- T4 S0 (centre money options). Every new key is optional, so settings saved before this migration stay valid;
  -- a key that is present must be right. assets/js/org-settings.js holds the labels and defaults (tests/org-settings.test.js compares the enums).
  if s#>>'{tutor_pay,rate_model}' is not null and s#>>'{tutor_pay,rate_model}' not in ('per_lesson','per_hour','per_student_lesson','monthly_fixed','percent_of_fee') then raise exception 'Unknown tutor pay rate'; end if;
  if s#>>'{tutor_pay,percent_base}' is not null and s#>>'{tutor_pay,percent_base}' not in ('billed_after_discounts','list_price') then raise exception 'Unknown percentage pay base'; end if;
  if s#>>'{tutor_pay,part_payments}' is not null and s#>>'{tutor_pay,part_payments}' not in ('after_full','pro_rata') then raise exception 'Unknown part-payment pay rule'; end if;
  if s#>>'{tutor_pay,cancelled_lessons}' is not null and s#>>'{tutor_pay,cancelled_lessons}' not in ('pay_if_charged','pay_rate','pay_nothing') then raise exception 'Unknown cancelled-lesson pay rule'; end if;
  if s#>>'{tutor_pay,group_count}' is not null and s#>>'{tutor_pay,group_count}' not in ('attended','enrolled') then raise exception 'Unknown group pay count'; end if;
  if s#>>'{billing,deposit,mode}' is not null and s#>>'{billing,deposit,mode}' not in ('none','fixed','percent_first_month') then raise exception 'Unknown deposit mode'; end if;
  if s#>>'{billing,deposit,due}' is not null and s#>>'{billing,deposit,due}' not in ('with_first_invoice','before_first_lesson') then raise exception 'Unknown deposit due rule'; end if;
  if s#>>'{billing,deposit,waived_by}' is not null and s#>>'{billing,deposit,waived_by}' not in ('owner','issue_invoices','nobody') then raise exception 'Unknown deposit waiver rule'; end if;
  if s#>>'{billing,deposit,release}' is not null and s#>>'{billing,deposit,release}' not in ('refund_full','refund_less_unpaid','admin_decides') then raise exception 'Unknown deposit release rule'; end if;
  if s#>>'{billing,deposit,refund_approved_by}' is not null and s#>>'{billing,deposit,refund_approved_by}' not in ('owner','staff','four_eyes') then raise exception 'Unknown deposit refund approver'; end if;
  if s#>>'{billing,late_fee,repeat}' is not null and s#>>'{billing,late_fee,repeat}' not in ('none','once','monthly') then raise exception 'Unknown late fee repeat'; end if;
  if s#>>'{billing,late_fee,type}' is not null and s#>>'{billing,late_fee,type}' not in ('fixed','percent') then raise exception 'Unknown late fee type'; end if;
  if s#>>'{billing,late_fee,show_as}' is not null and s#>>'{billing,late_fee,show_as}' not in ('next_invoice_line','own_invoice') then raise exception 'Unknown late fee placement'; end if;
  if s#>>'{billing,late_fee,waived_by}' is not null and s#>>'{billing,late_fee,waived_by}' not in ('owner','issue_invoices') then raise exception 'Unknown late fee waiver rule'; end if;
  if s#>>'{lessons,class_type}' is not null and s#>>'{lessons,class_type}' not in ('one_to_one','group','both') then raise exception 'Unknown class type'; end if;
  foreach k in array array['{billing,deposit,taxable}','{billing,deposit,top_up}','{billing,deposit,set_off_unpaid}','{billing,deposit,final_month}','{billing,trials,charged}'] loop
    v := s #> k::text[];
    if v is not null and jsonb_typeof(v) not in ('boolean','null') then raise exception 'Setting % must be yes or no', k; end if;
  end loop;
  for r in select * from (values
    ('{billing,deposit,percent_bp}', 0, 10000, 'Deposit percentage must be between 0% and 100%'),
    ('{billing,deposit,forfeit_notice_days}', 0, 90, 'Deposit notice must be 0-90 days'),
    ('{billing,late_fee,percent_bp}', 0, 10000, 'Late fee percentage must be between 0% and 100%'),
    ('{billing,late_fee,after_days}', 0, 365, 'Late fee grace period must be 0-365 days'),
    ('{billing,late_fee,cap_cents}', 0, 100000000, 'Late fee limit must be a whole number of cents, 0 to 100000000'),
    ('{billing,late_fee,amount_cents}', 0, 100000000, 'Late fee amount must be a whole number of cents, 0 to 100000000'),
    ('{billing,one_off_fees,deposit_cents}', 0, 100000000, 'Deposit amount must be a whole number of cents, 0 to 100000000'),
    ('{profile,next_invoice_number}', 1, 999999999, 'Next invoice number must be a whole number, 1 or more')
  ) as c(p, lo, hi, msg) loop
    v := s #> r.p::text[];
    if v is not null and jsonb_typeof(v) <> 'null' and not (case when jsonb_typeof(v) = 'number' and v::text ~ '^[0-9]{1,12}$'
         then (v#>>'{}')::bigint between r.lo and r.hi else false end) then
      raise exception '%', r.msg; end if;
  end loop;
  -- a percentage mode needs a real percentage (1 = 0.01%)
  if s#>>'{billing,deposit,mode}' = 'percent_first_month' and coalesce((s#>>'{billing,deposit,percent_bp}')::int, 0) < 1 then
    raise exception 'Deposit percentage must be between 0.01%% and 100%%'; end if;
  if s#>>'{billing,late_fee,type}' = 'percent' and coalesce((s#>>'{billing,late_fee,percent_bp}')::int, 0) < 1 then
    raise exception 'Late fee percentage must be between 0.01%% and 100%%'; end if;
end $$;

-- #####################################################################################################
-- ### PART 11 of 21 — centre invoice / payment tables
-- ### source branch: claude/t4-s1-tables   file: db/migration_centre_money.sql   undo: db/migration_centre_money_down.sql
-- ### (if an error appears, search this file for the nearest "### PART" line above the error line: that is the part that failed)
-- #####################################################################################################
-- =====================================================================================================
-- T4 step S1 — centre money: document, payment and numbering TABLES (database only, no screens)     undo: migration_centre_money_down.sql
-- =====================================================================================================
-- Run order everywhere: org_foundation → billing → attendance → tutor_access → org_delete → function_lockdown → org_separation →
--   staff_home → staff_students → staff_attendance → staff_charges → staff_trials → staff_timetable → centre_money.
-- Run on the DEV project first. LIVE only when the owner says ship (SELECT preview not needed: this adds tables and functions and reads or
-- changes no existing row; its only touch on an existing table is one unique index on lessons(id, org_id), where id is already the key).
-- Safe to run twice.
--
-- WHY NEW TABLES: the solo `invoices` table has tutor_id not null and keeps HTML in `data`, so it stays untouched (solo flows must not change).
-- Everything here lives in centres only: a row for a solo organisation is refused.
--
-- THE TABLES (all have org_id; every link to another table is a composite (id, org_id) key, so a row can never point at another centre's data)
--   org_counters               one counter per organisation and series ('invoice' = lesson + deposit + late-fee documents, ONE gap-free series;
--                              'credit_note' = its own series). The first number can be set once, before anything is issued.
--   centre_invoices            one table for the four kinds of document: lesson / deposit / late_fee / credit_note. draft → issued (or void,
--                              only from draft). A draft has NO number; the number is taken from the counter in the very statement that issues
--                              the document, so a failed issue leaves no gap. Once issued, nothing about it can change (corrections are credit
--                              notes). Money columns are whole cents; the totals must equal centre_gst_totals(...) of the lines.
--   centre_invoice_lines       lines of a DRAFT only (frozen with the invoice); a lesson can be billed once.
--   centre_payments            append-only. A payment is never edited or deleted: a mistake is a REVERSAL row (kind 'reversal', reverses_payment_id).
--   centre_payment_allocations append-only. Which payment covers which invoice, in cents. A reversal's allocations are negative.
--
-- WHO CAN READ (row-level security; centres only, solo owners read nothing): invoices, lines, counters = issue_invoices;
--   payments, allocations = record_payments; totals = centre_revenue_totals() for view_revenue. Owners can do everything. Tutors, parents,
--   switched-off staff, strangers and anonymous callers read nothing. NO table has an insert/update/delete policy: browsers write nothing here;
--   writes come only from functions added in the next steps (S2+). The two functions below that browsers may call do not write money.
--
-- AUDIT: every table has an audit trigger like the rest of the app, but free-text fields (payment reference, payer name, notes, reasons,
--   line descriptions) are replaced by "[redacted]" in the audit copy, because they can hold names and account fragments (PDPA).
-- =====================================================================================================

create unique index if not exists lessons_id_org on public.lessons(id, org_id);

-- ---------------------------------------------------------------------------------------------------
-- 1. whole-cent arithmetic in SQL (the source for issued documents; assets/js/money.js is the same maths in the browser)
-- ---------------------------------------------------------------------------------------------------
-- a / b rounded half AWAY from zero, integers only (b > 0). Mirrors Money.divRound.
create or replace function public.centre_div_round(a bigint, b bigint) returns bigint
language plpgsql immutable set search_path = public as $$
declare x bigint; q bigint;
begin
  if b is null or b <= 0 then raise exception 'denominator must be positive'; end if;
  if a is null then return null; end if;
  x := abs(a); q := x / b;
  if (x - q * b) * 2 >= b then q := q + 1; end if;
  return case when a < 0 then -q else q end;
end $$;

-- GST once per invoice, half up. Mirrors Money.gstForInvoice(subtotal, rateBp, inclusive, registered).
--   exclusive: gst = pct(subtotal), total = subtotal + gst        inclusive: gst = subtotal·rate / (10000 + rate), net = subtotal − gst
--   not registered (or rate 0): no GST.      p_subtotal is the sum of the lines (an inclusive price list sums to the total).
create or replace function public.centre_gst_totals(p_subtotal bigint, p_rate_bp int, p_inclusive boolean, p_registered boolean)
returns table(net_cents bigint, gst_cents bigint, total_cents bigint)
language plpgsql immutable set search_path = public as $$
declare g bigint;
begin
  if p_subtotal is null then raise exception 'subtotal is required'; end if;
  if not coalesce(p_registered, false) or coalesce(p_rate_bp, 0) = 0 then
    return query select p_subtotal, 0::bigint, p_subtotal; return;
  end if;
  if p_rate_bp < 0 or p_rate_bp > 5000 then raise exception 'GST rate must be between 0 and 5000 basis points'; end if;
  if coalesce(p_inclusive, false) then
    g := centre_div_round(p_subtotal * p_rate_bp, 10000 + p_rate_bp);
    return query select p_subtotal - g, g, p_subtotal;
  else
    g := centre_div_round(p_subtotal * p_rate_bp, 10000);
    return query select p_subtotal, g, p_subtotal + g;
  end if;
end $$;

-- The GST rules a centre has on a day (from its settings) applied to a subtotal: what S2 will copy onto a draft before issuing it.
-- Registered or not, rate, and whether prices are entered including GST all come from org_settings_on(org, day).
create or replace function public.centre_invoice_gst(p_org uuid, p_subtotal bigint, p_day date default current_date)
returns table(gst_registered boolean, gst_rate_bp int, gst_inclusive boolean, net_cents bigint, gst_cents bigint, total_cents bigint)
language plpgsql stable security definer set search_path = public as $$
declare s jsonb := org_settings_on(p_org, p_day); reg boolean; rate int; inc boolean;
begin
  if s is null then raise exception 'NOT_FOUND' using errcode = 'P0001'; end if;
  reg  := coalesce((s#>>'{profile,gst_registered}')::boolean, false);
  rate := case when reg then coalesce((s#>>'{profile,gst_rate_bp}')::int, 0) else 0 end;
  inc  := coalesce((s#>>'{profile,gst_inclusive}')::boolean, false);
  return query select reg, rate, inc, t.net_cents, t.gst_cents, t.total_cents from centre_gst_totals(p_subtotal, rate, inc, reg) t;
end $$;

-- ---------------------------------------------------------------------------------------------------
-- 2. the tables
-- ---------------------------------------------------------------------------------------------------
create table if not exists public.org_counters (
  org_id      uuid not null references public.organisations(id) on delete cascade,
  series      text not null check (series in ('invoice', 'credit_note')),
  next_number int  not null default 1 check (next_number >= 1),
  locked      boolean not null default false,        -- true from the first number handed out: the opening number can't be changed any more
  created_at  timestamptz not null default now(),
  primary key (org_id, series)
);

create table if not exists public.centre_invoices (
  id            uuid primary key default gen_random_uuid(),
  org_id        uuid not null references public.organisations(id) on delete cascade,
  kind          text not null check (kind in ('lesson', 'deposit', 'late_fee', 'credit_note')),
  series        text generated always as (case when kind = 'credit_note' then 'credit_note' else 'invoice' end) stored,
  status        text not null default 'draft' check (status in ('draft', 'issued', 'void')),
  number_seq    int check (number_seq >= 1),
  number_text   text,
  household_id  uuid,
  student_id    uuid,
  credits_invoice_id uuid,                            -- credit notes only: the invoice being credited
  period_start  date,
  period_end    date,
  issue_date    date,
  due_date      date,
  gst_registered boolean not null default false,      -- the GST rules the totals were computed with (frozen on the document)
  gst_rate_bp   int not null default 0 check (gst_rate_bp between 0 and 5000),
  gst_inclusive boolean not null default false,
  net_cents     bigint not null default 0,            -- before GST (inclusive pricing: the total minus the GST inside it)
  gst_cents     bigint not null default 0,
  total_cents   bigint not null default 0,
  reason        text,                                  -- credit notes: why (free text, redacted in the audit copy)
  void_reason   text,
  created_by    uuid default auth.uid(),
  created_at    timestamptz not null default now(),
  issued_by     uuid,
  issued_at     timestamptz,
  voided_at     timestamptz,
  unique (id, org_id),
  foreign key (household_id, org_id) references public.households(id, org_id),
  foreign key (student_id, org_id)   references public.students(id, org_id),
  foreign key (credits_invoice_id, org_id) references public.centre_invoices(id, org_id),
  check (total_cents = net_cents + gst_cents),
  check (net_cents >= 0 and gst_cents >= 0),
  check ((status = 'issued') = (number_seq is not null and number_text is not null)),
  check (status <> 'issued' or (household_id is not null or student_id is not null)),
  check ((kind = 'credit_note') = (credits_invoice_id is not null)),
  check (status <> 'issued' or (issue_date is not null and issued_at is not null)),
  check (period_start is null or period_end is null or period_end >= period_start),
  check (due_date is null or issue_date is null or due_date >= issue_date),
  check (status <> 'void' or (void_reason is not null and voided_at is not null))
);
create unique index if not exists centre_invoices_number on public.centre_invoices(org_id, series, number_seq) where number_seq is not null;
create index if not exists centre_invoices_org on public.centre_invoices(org_id, status, issue_date desc);
create index if not exists centre_invoices_household on public.centre_invoices(org_id, household_id);
create index if not exists centre_invoices_credits on public.centre_invoices(credits_invoice_id) where credits_invoice_id is not null;

create table if not exists public.centre_invoice_lines (
  id          uuid primary key default gen_random_uuid(),
  org_id      uuid not null references public.organisations(id) on delete cascade,
  invoice_id  uuid not null,
  position    int  not null default 1 check (position >= 1),
  lesson_id   uuid,                                    -- the lesson this line bills (lesson invoices); a lesson is billed once
  description text not null check (length(trim(description)) between 1 and 300),
  qty         int  not null default 1 check (qty >= 1),
  unit_cents  bigint not null,                         -- negative = a discount line
  line_cents  bigint generated always as (qty * unit_cents) stored,
  created_at  timestamptz not null default now(),
  unique (id, org_id),
  foreign key (invoice_id, org_id) references public.centre_invoices(id, org_id) on delete cascade,
  foreign key (lesson_id, org_id)  references public.lessons(id, org_id)
);
create index if not exists centre_invoice_lines_invoice on public.centre_invoice_lines(invoice_id);
create index if not exists centre_invoice_lines_lesson on public.centre_invoice_lines(lesson_id) where lesson_id is not null;

create table if not exists public.centre_payments (
  id            uuid primary key default gen_random_uuid(),
  org_id        uuid not null references public.organisations(id) on delete cascade,
  kind          text not null default 'payment' check (kind in ('payment', 'reversal')),
  reverses_payment_id uuid,                            -- a reversal row points at the payment it cancels (that payment is "reversed by" this row)
  household_id  uuid not null,
  method        text not null check (method in ('manual_paynow', 'bank', 'cash', 'cheque', 'other')),
  amount_cents  bigint not null check (amount_cents > 0),
  received_on   date not null,
  reference     text,                                  -- free text (invoice number, bank reference...). Never a full account number. Redacted in audit.
  payer_name    text,
  note          text,
  recorded_by   uuid default auth.uid(),
  created_at    timestamptz not null default now(),
  unique (id, org_id),
  foreign key (household_id, org_id) references public.households(id, org_id),
  foreign key (reverses_payment_id, org_id) references public.centre_payments(id, org_id),
  check ((kind = 'reversal') = (reverses_payment_id is not null))
);
create unique index if not exists centre_payments_one_reversal on public.centre_payments(reverses_payment_id) where reverses_payment_id is not null;
create index if not exists centre_payments_org on public.centre_payments(org_id, received_on desc);
create index if not exists centre_payments_household on public.centre_payments(org_id, household_id);

create table if not exists public.centre_payment_allocations (
  id          uuid primary key default gen_random_uuid(),
  org_id      uuid not null references public.organisations(id) on delete cascade,
  payment_id  uuid not null,
  invoice_id  uuid not null,
  cents       bigint not null check (cents <> 0),      -- positive on a payment, negative on its reversal
  created_by  uuid default auth.uid(),
  created_at  timestamptz not null default now(),
  unique (id, org_id),
  foreign key (payment_id, org_id) references public.centre_payments(id, org_id),
  foreign key (invoice_id, org_id) references public.centre_invoices(id, org_id)
);
create index if not exists centre_alloc_payment on public.centre_payment_allocations(payment_id);
create index if not exists centre_alloc_invoice on public.centre_payment_allocations(invoice_id);

-- ---------------------------------------------------------------------------------------------------
-- 3. guards
-- ---------------------------------------------------------------------------------------------------
-- 3a. centres only
create or replace function public.centre_money_org_guard() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if not exists (select 1 from organisations o where o.id = new.org_id and o.kind = 'centre') then
    raise exception 'Centre money tables are for centres only' using errcode = '42501';
  end if;
  return new;
end $$;

-- the shared exception for deleting a whole organisation (same rule as audit_immutable: only inside org_delete_solo, never a browser role)
create or replace function public.centre_money_deleting(p_org uuid) returns boolean
language sql stable set search_path = public as $$
  select coalesce(current_setting('td.deleting_org', true), '') <> '' and coalesce(current_setting('td.deleting_org', true), '') = p_org::text
         and current_user not in ('anon', 'authenticated', 'service_role')
$$;

-- 3b. numbering: take the next number of a series. INTERNAL (no browser may call it). Gap-free because the counter row is locked and
--     incremented inside the transaction that issues the document: if that transaction fails, the increment is rolled back with it.
create or replace function public.centre_next_number(p_org uuid, p_series text) returns int
language plpgsql security definer set search_path = public as $$
declare n int;
begin
  if p_series not in ('invoice', 'credit_note') then raise exception 'Unknown number series'; end if;
  insert into org_counters(org_id, series) values (p_org, p_series) on conflict (org_id, series) do nothing;
  update org_counters set next_number = next_number + 1, locked = true
   where org_id = p_org and series = p_series returning next_number - 1 into n;
  return n;
end $$;

-- the opening number: "the next document will be number p_next". Owner only, centres only, only before the first number was handed out.
create or replace function public.centre_set_opening_number(p_org uuid, p_series text, p_next int) returns int
language plpgsql security definer set search_path = public as $$
declare cur record;
begin
  if auth.uid() is null or not exists (select 1 from organisations o where o.id = p_org and o.kind = 'centre') or not org_can(p_org, 'owner') then
    raise exception 'NOT_FOUND' using errcode = 'P0001';
  end if;
  if p_series not in ('invoice', 'credit_note') then raise exception 'NOT_ALLOWED: unknown number series' using errcode = '42501'; end if;
  if p_next is null or p_next < 1 or p_next > 999999999 then raise exception 'NOT_ALLOWED: the opening number must be a whole number from 1' using errcode = '42501'; end if;
  insert into org_counters(org_id, series) values (p_org, p_series) on conflict (org_id, series) do nothing;
  select * into cur from org_counters where org_id = p_org and series = p_series for update;
  if cur.locked or exists (select 1 from centre_invoices i where i.org_id = p_org and i.series = p_series and i.number_seq is not null) then
    raise exception 'NOT_ALLOWED: numbers have already been issued, so the opening number can''t be changed' using errcode = '42501';
  end if;
  update org_counters set next_number = p_next where org_id = p_org and series = p_series;
  return p_next;
end $$;

-- counters only ever go forward by one, and only once locked; the opening number may move freely before that
create or replace function public.centre_counter_guard() returns trigger
language plpgsql set search_path = public as $$
begin
  if tg_op = 'DELETE' then
    if centre_money_deleting(old.org_id) then return old; end if;
    raise exception 'org_counters is append-only';
  end if;
  if new.org_id <> old.org_id or new.series <> old.series then raise exception 'A counter can''t move'; end if;
  if old.locked and (not new.locked or new.next_number <> old.next_number + 1) then
    raise exception 'A document number can only go forward by one (numbers are never reused or skipped)';
  end if;
  if not old.locked and new.locked and new.next_number <> old.next_number + 1 then
    raise exception 'A document number can only go forward by one (numbers are never reused or skipped)';
  end if;
  return new;
end $$;

-- 3c. the invoice: draft → issued (number + frozen totals checked) | void; nothing else; issued and void rows never change
create or replace function public.centre_invoice_guard() returns trigger
language plpgsql security definer set search_path = public as $$
declare s jsonb; prefix text; sub bigint; nlines int; t record; credited bigint; inv record; day date;
begin
  if tg_op = 'DELETE' then
    if old.status = 'draft' or centre_money_deleting(old.org_id) then return old; end if;
    raise exception 'An issued or voided document can''t be deleted (issue a credit note instead)' using errcode = '42501';
  end if;
  if tg_op = 'INSERT' then
    if new.status <> 'draft' or new.number_seq is not null or new.number_text is not null then
      raise exception 'A new document starts as a draft with no number' using errcode = '42501';
    end if;
    return new;
  end if;
  -- UPDATE
  if old.status <> 'draft' then
    raise exception 'An % document can''t be changed (issue a credit note instead)', old.status using errcode = '42501';
  end if;
  if new.org_id <> old.org_id or new.kind <> old.kind then raise exception 'A document''s organisation and kind can''t change'; end if;
  if new.status = 'draft' then
    if new.number_seq is not null or new.number_text is not null then raise exception 'A draft has no number; it is given one when issued' using errcode = '42501'; end if;
    return new;
  end if;
  if new.status = 'void' then
    new.voided_at := coalesce(new.voided_at, now());
    if new.number_seq is not null or new.number_text is not null then raise exception 'A voided draft has no number' using errcode = '42501'; end if;
    return new;
  end if;
  -- issuing: validate, take the number, freeze
  select coalesce(sum(line_cents), 0), count(*) into sub, nlines from centre_invoice_lines where invoice_id = new.id;
  if nlines = 0 then raise exception 'A document needs at least one line before it is issued' using errcode = '42501'; end if;
  select * into t from centre_gst_totals(sub, new.gst_rate_bp, new.gst_inclusive, new.gst_registered);
  if t.net_cents <> new.net_cents or t.gst_cents <> new.gst_cents or t.total_cents <> new.total_cents then
    raise exception 'The totals don''t match the lines (expected net %, GST %, total %)', t.net_cents, t.gst_cents, t.total_cents using errcode = '42501';
  end if;
  if new.total_cents < 0 then raise exception 'A document''s total can''t be negative' using errcode = '42501'; end if;
  if new.kind = 'credit_note' then
    select * into inv from centre_invoices where id = new.credits_invoice_id and org_id = new.org_id;
    if inv.id is null or inv.status <> 'issued' or inv.kind = 'credit_note' then
      raise exception 'A credit note must credit an issued invoice' using errcode = '42501';
    end if;
    if new.reason is null or length(trim(new.reason)) = 0 then raise exception 'A credit note needs a reason' using errcode = '42501'; end if;
    perform pg_advisory_xact_lock(hashtextextended(inv.id::text, 0));
    select coalesce(sum(total_cents), 0) into credited from centre_invoices
     where credits_invoice_id = inv.id and status = 'issued' and id <> new.id;
    if credited + new.total_cents > inv.total_cents then
      raise exception 'Credit notes can''t add up to more than the invoice (invoice %, already credited %, this one %)', inv.total_cents, credited, new.total_cents using errcode = '42501';
    end if;
    if inv.household_id is distinct from new.household_id or inv.student_id is distinct from new.student_id then
      raise exception 'A credit note must be for the same household and student as its invoice' using errcode = '42501';
    end if;
  end if;
  day := coalesce(new.issue_date, (now() at time zone coalesce((select timezone from organisations where id = new.org_id), 'Asia/Singapore'))::date);
  s := org_settings_on(new.org_id, day);
  prefix := coalesce(nullif(trim(s#>>'{profile,invoice_prefix}'), ''), 'INV');
  new.number_seq := centre_next_number(new.org_id, case when new.kind = 'credit_note' then 'credit_note' else 'invoice' end);   -- (generated columns are not filled yet in a BEFORE trigger)
  new.number_text := case when new.kind = 'credit_note' then 'CN-' else '' end || prefix || '-' || new.number_seq;
  new.issue_date := day;
  new.issued_at := now();
  new.issued_by := coalesce(auth.uid(), new.created_by);
  return new;
end $$;

-- 3d. lines: only while the invoice is a draft; a lesson is billed once
create or replace function public.centre_line_guard() returns trigger
language plpgsql security definer set search_path = public as $$
declare inv record; r record := case when tg_op = 'DELETE' then old else new end;
begin
  select * into inv from centre_invoices where id = r.invoice_id and org_id = r.org_id;
  if inv.id is null then
    if tg_op = 'DELETE' then return old; end if;            -- the draft itself is being deleted (cascade)
    raise exception 'Unknown document';
  end if;
  if inv.status <> 'draft' then
    raise exception 'The lines of an % document can''t be changed (issue a credit note instead)', inv.status using errcode = '42501';
  end if;
  if tg_op = 'DELETE' then return old; end if;
  if tg_op = 'UPDATE' and (new.invoice_id <> old.invoice_id or new.org_id <> old.org_id) then raise exception 'A line can''t move to another document'; end if;
  if new.lesson_id is not null and (inv.kind = 'credit_note') then
    raise exception 'A credit note can''t bill a lesson' using errcode = '42501';
  end if;
  if new.lesson_id is not null and (tg_op = 'INSERT' or new.lesson_id is distinct from old.lesson_id) then
    perform pg_advisory_xact_lock(hashtextextended(new.lesson_id::text, 1));
    if exists (select 1 from centre_invoice_lines l join centre_invoices i on i.id = l.invoice_id and i.org_id = l.org_id
                where l.lesson_id = new.lesson_id and l.id <> new.id and i.status <> 'void') then
      raise exception 'That lesson is already billed on another document' using errcode = '23505';
    end if;
  end if;
  return new;
end $$;

-- 3e. payments: append-only; a reversal must match what it cancels. The household must own... (the household of the payment is checked by the FK)
create or replace function public.centre_payment_guard() returns trigger
language plpgsql security definer set search_path = public as $$
declare p record;
begin
  if tg_op in ('UPDATE', 'DELETE') then
    if tg_op = 'DELETE' and centre_money_deleting(old.org_id) then return old; end if;
    raise exception '% is append-only (record a reversal instead)', tg_table_name using errcode = '42501';
  end if;
  if new.kind = 'reversal' then
    select * into p from centre_payments where id = new.reverses_payment_id and org_id = new.org_id;
    if p.id is null or p.kind <> 'payment' then raise exception 'A reversal must cancel a payment of this centre' using errcode = '42501'; end if;
    if new.amount_cents <> p.amount_cents or new.household_id <> p.household_id or new.method <> p.method then
      raise exception 'A reversal must repeat the payment it cancels (same household, method and amount)' using errcode = '42501';
    end if;
    if new.received_on < p.received_on then raise exception 'A reversal can''t be dated before the payment' using errcode = '42501'; end if;
  end if;
  return new;
end $$;

-- a reversed payment must not keep money allocated: checked when the transaction commits, so the reversal and its negative allocations can be
-- written in either order inside one transaction
create or replace function public.centre_payment_reversal_check() returns trigger
language plpgsql security definer set search_path = public as $$
declare net bigint;
begin
  select coalesce(sum(a.cents), 0) into net from centre_payment_allocations a
   where a.org_id = new.org_id and a.payment_id in (new.id, new.reverses_payment_id);
  if net <> 0 then
    raise exception 'A reversed payment can''t keep money allocated to invoices (still allocated: % cents)', net using errcode = '23514';
  end if;
  return null;
end $$;

-- 3f. allocations: append-only; never more than the payment, never more than the invoice
create or replace function public.centre_alloc_guard() returns trigger
language plpgsql security definer set search_path = public as $$
declare p record; inv record; root uuid; pay_total bigint; chain_inv bigint; inv_total bigint; credited bigint;
begin
  if tg_op in ('UPDATE', 'DELETE') then
    if tg_op = 'DELETE' and centre_money_deleting(old.org_id) then return old; end if;
    raise exception '% is append-only (reverse the payment instead)', tg_table_name using errcode = '42501';
  end if;
  select * into p from centre_payments where id = new.payment_id and org_id = new.org_id;
  select * into inv from centre_invoices where id = new.invoice_id and org_id = new.org_id;
  if p.id is null or inv.id is null then raise exception 'Unknown payment or invoice'; end if;
  if inv.status <> 'issued' or inv.kind = 'credit_note' then raise exception 'Money can only be allocated to an issued invoice' using errcode = '42501'; end if;
  if inv.household_id is distinct from p.household_id and not exists (select 1 from students s where s.id = inv.student_id and s.org_id = inv.org_id and s.household_id = p.household_id) then
    raise exception 'The payment and the invoice belong to different households' using errcode = '42501';
  end if;
  if p.kind = 'payment' and new.cents < 0 then raise exception 'A payment can only be allocated, not negatively' using errcode = '42501'; end if;
  if p.kind = 'reversal' and new.cents > 0 then raise exception 'A reversal can only un-allocate (negative cents)' using errcode = '42501'; end if;
  root := coalesce(p.reverses_payment_id, p.id);
  perform pg_advisory_xact_lock(hashtextextended(root::text, 2));
  perform pg_advisory_xact_lock(hashtextextended(inv.id::text, 3));
  -- per payment (with its reversal): between 0 and the amount
  select coalesce(sum(a.cents), 0) + new.cents into pay_total from centre_payment_allocations a
   where a.org_id = new.org_id and a.payment_id in (select id from centre_payments where org_id = new.org_id and (id = root or reverses_payment_id = root));
  if pay_total > (select amount_cents from centre_payments where id = root and org_id = new.org_id) then
    raise exception 'Allocations can''t add up to more than the payment' using errcode = '23514';
  end if;
  if pay_total < 0 then raise exception 'Allocations can''t go below zero' using errcode = '23514'; end if;
  -- this payment's share of this invoice stays between 0 and what it put there
  select coalesce(sum(a.cents), 0) + new.cents into chain_inv from centre_payment_allocations a
   where a.org_id = new.org_id and a.invoice_id = new.invoice_id
     and a.payment_id in (select id from centre_payments where org_id = new.org_id and (id = root or reverses_payment_id = root));
  if chain_inv < 0 then raise exception 'Can''t un-allocate more than was allocated to that invoice' using errcode = '23514'; end if;
  -- per invoice: never more than what is still owed after credit notes
  select coalesce(sum(a.cents), 0) + new.cents into inv_total from centre_payment_allocations a where a.org_id = new.org_id and a.invoice_id = new.invoice_id;
  select coalesce(sum(c.total_cents), 0) into credited from centre_invoices c where c.credits_invoice_id = inv.id and c.status = 'issued';
  if inv_total > inv.total_cents - credited then
    raise exception 'Allocations can''t add up to more than the invoice (invoice %, credited %, allocated would be %)', inv.total_cents, credited, inv_total using errcode = '23514';
  end if;
  return new;
end $$;

-- 3g. audit with redaction (same shape as audit_row, plus free-text fields replaced)
create or replace function public.centre_money_audit() returns trigger
language plpgsql security definer set search_path = public as $$
declare b jsonb; a jsonb; k text; redact text[] := array['reference', 'payer_name', 'note', 'reason', 'void_reason', 'description'];
begin
  if coalesce(current_setting('td.skip_audit', true), '') = '1' then return null; end if;
  b := case when tg_op in ('UPDATE', 'DELETE') then to_jsonb(old) end;
  a := case when tg_op in ('INSERT', 'UPDATE') then to_jsonb(new) end;
  foreach k in array redact loop
    if b ? k and b->>k is not null then b := jsonb_set(b, array[k], '"[redacted]"'); end if;
    if a ? k and a->>k is not null then a := jsonb_set(a, array[k], '"[redacted]"'); end if;
  end loop;
  insert into audit_log(org_id, actor, action, table_name, row_id, before, after)
  values (coalesce((a->>'org_id')::uuid, (b->>'org_id')::uuid), auth.uid(), lower(tg_op), tg_table_name,
          coalesce(a->>'id', b->>'id', coalesce(a->>'org_id', b->>'org_id') || ':' || coalesce(a->>'series', b->>'series')), b, a);
  return null;
end $$;

do $$
declare t text;
begin
  foreach t in array array['org_counters', 'centre_invoices', 'centre_invoice_lines', 'centre_payments', 'centre_payment_allocations'] loop
    execute format('drop trigger if exists centre_money_org_guard on public.%I', t);
    execute format('create trigger centre_money_org_guard before insert on public.%I for each row execute function public.centre_money_org_guard()', t);
    execute format('drop trigger if exists audit_row on public.%I', t);
    execute format('create trigger audit_row after insert or update or delete on public.%I for each row execute function public.centre_money_audit()', t);
  end loop;
end $$;
drop trigger if exists centre_counter_guard on public.org_counters;
create trigger centre_counter_guard before update or delete on public.org_counters for each row execute function public.centre_counter_guard();
drop trigger if exists centre_invoice_guard on public.centre_invoices;
create trigger centre_invoice_guard before insert or update or delete on public.centre_invoices for each row execute function public.centre_invoice_guard();
drop trigger if exists centre_line_guard on public.centre_invoice_lines;
create trigger centre_line_guard before insert or update or delete on public.centre_invoice_lines for each row execute function public.centre_line_guard();
drop trigger if exists centre_payment_guard on public.centre_payments;
create trigger centre_payment_guard before insert or update or delete on public.centre_payments for each row execute function public.centre_payment_guard();
drop trigger if exists centre_payment_reversal_check on public.centre_payments;
create constraint trigger centre_payment_reversal_check after insert on public.centre_payments deferrable initially deferred
  for each row when (new.kind = 'reversal') execute function public.centre_payment_reversal_check();
drop trigger if exists centre_alloc_guard on public.centre_payment_allocations;
create trigger centre_alloc_guard before insert or update or delete on public.centre_payment_allocations for each row execute function public.centre_alloc_guard();

-- ---------------------------------------------------------------------------------------------------
-- 4. access: read only, by permission; nobody writes from a browser
-- ---------------------------------------------------------------------------------------------------
alter table public.org_counters enable row level security;
alter table public.centre_invoices enable row level security;
alter table public.centre_invoice_lines enable row level security;
alter table public.centre_payments enable row level security;
alter table public.centre_payment_allocations enable row level security;

